quests[34715] = { id = 34715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Flag: Shamanstone Summons" }
quests[34716] = { id = 34716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mo'mor weiß mehr", description = "Wir wissen, dass sich die Anführerin des Kriegshymnentrupps, der die Karawane angegriffen hat, in Telaar befindet. Sie hat den Bauplan.\n\nWir wissen nicht, wo genau sie sich aufhält, aber es gibt jemanden, der Bescheid wissen könnte.\n\nAls Verteidiger Mo'mor zuletzt gesichtet wurde, war er am Leben – allerdings geriet er in Gefangenschaft. Falls er noch lebt, könnte er wissen, wo sich der Bauplan befindet.", sourceObjective = "Findet Verteidiger Mo'mor in Telaar.", completion = "Bitte verzeiht – ich bin nicht in der Lage, aufzustehen, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[34717] = { id = 34717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Gerechte Pfeilspitze", description = "Es versteht sich von selbst, dass wir Euch dabei helfen werden, alle Kämpfer des Kriegshymnenklans dort draußen zu erledigen.\n\nZettelt einfach einen Kampf an – wir werden ihn mit extremer Härte beenden.", sourceObjective = "Tötet 15 Kriegshymnenkrieger in Telaar.", completion = "Diese Vergeltung sollte den Willen meiner Rangari gestärkt haben.\n\nDer Verlust Telaars und vieler unserer Freunde hat uns schwer zugesetzt.\n\nVielen Dank, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[34718] = { id = 34718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Anderen", description = "Es gibt ein paar Überlebende. Ich habe gesehen, wie sie sich während der Kämpfe auf Richter Khan geworfen haben.\n\nWas noch wichtiger ist: Ich kann die kleine Isel schluchzen hören. Sie ist in der Nähe. Hoffentlich lebt ihre Mutter noch.\n\nEuer Zwergenfreund, Hansel, hat versucht, uns hier rauszuholen. Er dachte, dass er es allein mit dem Kriegshymnenklan aufnehmen könnte. Leider kann ich nicht sagen, was mit ihm passiert ist.", sourceObjective = "Rettet Richter Khan, Versorgerin Felaani und Isel sowie Hansel Bleihand.", completion = "Khan! Nein!... Er hatte gerade erst seine Beförderung erhalten. Er hatte sein ganzes Leben vor sich, und jetzt... alles vorbei.\n\nDanke, dass Ihr die anderen rausgeholt habt. Möge das Licht... ach, vergesst es.", sourceObjectiveStatus = "unverified-source-field" }
quests[34719] = { id = 34719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "... und meinen Hammer", description = "Als sie mich gefangen nahmen, schnappten die Hunde vom Kriegshymnenklan sich meinen Hammer. Werdet Ihr mir dabei helfen, ihn zurückzubekommen?\n\nIch frage Euch nur, weil es sich um eine heilige Reliquie handelt. Wir müssen ihn den Orcs allein deswegen abnehmen, damit er zurück nach Auchindoun gebracht werden kann.\n\nVielleicht wird ihn dann ein würdiger Verteidiger des Lichts ergreifen, um mit ihm die Feinde der Draenei niederzustrecken.", sourceObjective = "Beschafft Mo'mors heiligen Hammer zurück.", progress = "Ich kann nicht mehr richtig sehen. Mit mir geht es bald zu Ende.", completion = "Habt Dank für Eure Güte, {name}. Vielleicht kann ich wenigstens einen Teil meiner Ehre retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[34720] = { id = 34720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Gerechte Pfeilspitze", description = "Es versteht sich von selbst, dass jemand sich um die Kämpfer des Kriegshymnenklans in Telaar kümmern muss. Rangari Ogir und seine Streitkräfte beim Hochstand werden Euch dabei helfen, alle Orcs dort draußen zu erledigen.\n\nZettelt einfach einen Kampf an – sie werden ihn mit extremer Härte beenden.", sourceObjective = "Tötet 15 Kriegshymnenkrieger in Telaar.", sourceObjectiveStatus = "unverified-source-field" }
quests[34721] = { id = 34721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach der Seherin", description = "Wir beobachten Euch seit einiger Zeit.\n\nSeherin Malune, die Hüterin der Erinnerungen, hat um eine Audienz mit Euch gebeten, <Abenteurer/Abenteurerin>.\n\nSie hat schon vor langer Zeit die Ankunft <eines großen Helden/einer großen Heldin> vorhergesagt, <der/die> den lauernden Schatten vernichten würde. Wir glauben, dass Ihr <dieser Held/diese Heldin> seid.\n\nKommt zur Abendlichtinsel, unweit von hier im Südosten, und erfüllt Eure Bestimmung.", sourceObjective = "Sprecht mit Seherin Malune auf der Abendlichtinsel in Talador.", completion = "Ich bin Seherin Malune, die große Hüterin der Erinnerungen. Es ist mir eine Ehre, Euch endlich zu treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34722] = { id = 34722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durotan hat nach Euch gefragt", description = "Durotan hat nach dir gefragt, Mann.", sourceObjective = "Sprecht mit Durotan in Eurer Garnison.", sourceObjectiveStatus = "unverified-source-field" }
quests[34723] = { id = 34723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenfausthafen" }
quests[34724] = { id = 34724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vergessenen Höhlen" }
quests[34725] = { id = 34725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Meereshydra" }
quests[34726] = { id = 34726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Fahlspinnenbrutmutter" }
quests[34727] = { id = 34727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Meeresfürst Torglork" }
quests[34728] = { id = 34728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schimmermoor" }
quests[34729] = { id = 34729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Na'Shras Blutschwur", description = "Ihr habt mir einen großen Dienst erwiesen. Diese Klinge gehört Euch jetzt ebenso wie mir.\n\nIch biete Euch einen Blutschwur an: Ich werde Euch dienen und Euren Truppen mein Wissen über Klingen und den Bergbau zur Verfügung stellen.\n\nSeid Ihr damit einverstanden?", sourceObjective = "Nehmt den Blutschwur von Klingenmeisterin Na'Shra an.", completion = "Ihr habt mir einen großen Dienst erwiesen. Diese Klinge gehört Euch jetzt ebenso wie mir.\n\nIch biete Euch einen Blutschwur an: Ich werde Euch dienen und Euren Truppen mein Wissen über Klingen und den Bergbau zur Verfügung stellen.\n\nSeid Ihr damit einverstanden?", sourceObjectiveStatus = "unverified-source-field" }
quests[34730] = { id = 34730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lokras Blutschwur", description = "Ihr habt mir einen großen Dienst erwiesen. Diese Klinge gehört Euch jetzt ebenso wie mir.\n\nIch biete Euch einen Blutschwur an: Ich werde Euch dienen und Euren Truppen mein Wissen über Klingen und den Bergbau zur Verfügung stellen.\n\nSeid Ihr damit einverstanden?", sourceObjective = "Nehmt den Blutschwur von Klingenmeisterin Na'Shra an.", sourceObjectiveStatus = "unverified-source-field" }
quests[34731] = { id = 34731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwur von Schattenjäger Rala", sourceObjective = "Meine Schwester hat andere Sachen zu tun, aber ich habe die Erlaubnis vom alten Vol'jin, Euch meine Dienste anzubiet'n!\n\nIhr habt Euren Wert bewies'n, und Ihr habt getan, was getan werd'n musste.\n\nIch werde Euch folgen, Scheff, wenn Ihr das wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[34732] = { id = 34732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mulvericks Dienstangebot", sourceObjective = "Champion, ich schulde Euch mein Leben und meine Ehre. Gestattet mir, diese Schuld zurückzuzahlen, indem ich mich Eurem Befehl unterstelle.\n\nIhr werdet feststellen, dass ich ein furchteinflößender Jäger bin. Außerdem habe ich die Kunst gemeistert, einen Rylak zu reiten. Dies können nur wenige Frostwölfe von sich behaupten.\n\nNehmt Ihr meine Dienste an?", sourceObjectiveStatus = "unverified-source-field" }
quests[34733] = { id = 34733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daggs Dienste", sourceObjective = "Die sich dann fragen müssen: \"Haben wir Dagg gefangt oder hat Dagg uns gefangt?\"\n\nGroßer Held mich auffliegen gelassen hat! Aber du bist besonders, denkt Dagg. Dagg ist der Meister der Tahr-Nung und Dagg wollen zu euch gehören.\n\nDagg ist da absolut einer Meinung.", sourceObjectiveStatus = "unverified-source-field" }
quests[34734] = { id = 34734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Loyalty of Olin Umberhide", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[34736] = { id = 34736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir brauchen Vorräte", description = "Kommandant, uns're Truppen sind auf'n Frostkampf nicht vorbereitet. Ich war so frei, 'n paar unserer Schattenjäger nordwärts zu schick'n, um 'ne Versorgungsbasis zu errichten.\n\nIhr möchtet bestimmt wissen, wie sie vorangekommen sind. Sucht nach einer Senke zwischen den Knirschenden Ebenen und der Wilden Schlucht.", sourceObjective = "Sprecht mit Schattenjäger Rala an der Dunkelspeerspalte.", completion = "Vorsicht, Scheff! Passt auf, wo Ihr hintretet. Der Boden is' hier überall am Aufbrech'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[34737] = { id = 34737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Schatten", description = "Die bösen Orcs haben versucht, mich zu fangen, aber ich habe mich davongeschlichen. Ich bin gut im Verstecken.\n\nAlle bösen Orcs sind böse, aber ich habe mir die Namen der gemeinsten gemerkt, nur falls jemand kommt und mich rettet.\n\n<Luuka holt tief Luft.>\n\nUngra, Gurran und... ähm... oh! Ankova.\n\nWerdet Ihr mich vor ihnen beschützen?", sourceObjective = "Tötet Ungra, Zuchtmeister Gurran und Ankova die Gefallene.", progress = "Wie geht es mit Eurer Mission voran?", completion = "Gut gemacht.\n\nHaltet Euch bereit für den Aufbruch. Wir haben möglicherweise das Überraschungsmoment in dieser Höhle auf unserer Seite, doch dieser Vorteil wird nicht von Dauer sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[34739] = { id = 34739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schattenmondklan", description = "Wir werden die verwundeten Gefangenen beschützen und sichergehen, dass Kargath es nicht durch das Geröll schafft. Geht vor und räumt die Höhle, {name}.", sourceObjective = "Tötet 10 Schattenmondorcs oder Leerenwölfe in den Schattenhallen.", completion = "Ihr kämpft außergewöhnlich gut, {name}... besser als ich je zu hoffen gewagt habe.\n\nDa die Orcs aus dem Weg geräumt sind, sollten Khadgar und Maraad jetzt in der Lage sein, den Rest unserer Gruppe sicher durch die Höhle zu führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34740] = { id = 34740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yrel", description = "Verzeiht mir, ich bin ein wenig durcheinander – ich habe noch nie jemanden getötet.\n\nIch heiße Yrel und bin eine Schülerin aus Karabor.\n\nIhr sagt, Ihr hättet eine ARMEE bei Euch? Das Licht wacht heute scheinbar wirklich über mich.\n\nDann werde ich Euch folgen. Geht voran, {name}.", sourceObjective = "Bringt Yrel in Sicherheit.", completion = "Da oben – das ist Keli'dan der Zerstörer. Zweifellos weiß er über unsere Anwesenheit Bescheid und versucht, seinem Kriegsherrn von unserem Gefängnisausbruch zu erzählen.\n\nWir müssen ihn ausschalten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[34741] = { id = 34741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keli'dan der Zerstörer", description = "Einer von Ner'zhuls Gehilfen ist noch übrig. Er befindet sich weiter vorne und der Höhlenausgang liegt nicht weit hinter ihm.\n\nIch werde zurückgehen und Khadgar sagen, dass die Höhle sicher ist. Wir treffen uns, wenn Ihr Euch um Keli'dan gekümmert habt!", sourceObjective = "Tötet Keli'dan den Zerstörer.", completion = "Gute Arbeit in der Höhle, aber noch ist keine Zeit zum Ausruhen.\n\nWir haben die Initiative und müssen in Bewegung bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[34742] = { id = 34742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungsmodus der Oberen Schwarzfelsspitze – Trostpreis (N.)" }
quests[34743] = { id = 34743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Torvaths Kristallklinge" }
quests[34746] = { id = 34746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schilde unten!", description = "Habt Ihr das gehört? Sie haben den Schild aktiviert. Jetzt gibt es keinen Weg mehr nach Telaar hinein.\n\nIhr müsst den Schild ausschalten. Das werdet Ihr nur schaffen, indem Ihr den Arkonitkristall zerstört.\n\nMacht Euch keine Sorgen um mich. Ihr werdet zwei Fliegen mit einer Klappe schlagen: Rudelführerin Kargor ist diejenige, die Eure Baupläne gestohlen hat.", sourceObjective = "Zerstört den Arkonitkristall und beschafft die Garnisonsbaupläne von Rudelführerin Kargor.", progress = "Gute Nachrichten?", completion = "Perfekt! Ihr habt die Baupläne beschafft.\n\nJetzt muss nur noch eines erledigt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[34747] = { id = 34747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ehre eines Klingenmeisters", sourceObjective = "Ich habe keinen Klan. Die Brennende Klinge ist für mich gestorben. Vielleicht werde ich eines Tages meinen eigenen Klan gründen.\n\nIn der Zwischenzeit wäre es mir eine Ehre, an Eurer Seite zu kämpfen. Ihr habt mich befreit und gut gekämpft.\n\nWir können viel voneinander lernen. Was meint Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[34751] = { id = 34751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Achtung, Schock!", description = "Ey, ich brauche Hilfe mit diesem kaputten Roboter. Ich habe verflixt noch mal Hunger!\n\nIch habe den Genussbot 8000 gebaut, um die Trüffel Draenors zu finden, und was macht er? Er schwimmt zu einer verdammten Insel und löst dabei einen Kurzschluss im Energiefluktuator aus.\n\nIch habe ihn an diese Batterie angeschlossen, aber es kommt nicht genug Saft, um den Fluktuator zu überbrücken.\n\nSeid doch so lieb und bringt mir die Blitzblasen der Zitteraale im See, ja? Die sollten ausreichen.", sourceObjective = "Sammelt 6 Blitzbeutel von Seegrundschockern in Talador.", progress = "Hast du das Zeug, Kumpel?", completion = "Gute Arbeit! Wenn man bedenkt, dass Ihr ein {class} seid, seid Ihr ein echt guter Geschäftspartner.\n\nAlso, dann drücken wir die jetzt einfach mal in diesen Schlitz...", sourceObjectiveStatus = "unverified-source-field" }
quests[34755] = { id = 34755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Minenhauptmann Bashgar" }
quests[34756] = { id = 34756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zauberhafte Illusion", description = "Reshad ist weitaus mächtiger, als man auf den ersten Blick vermuten könnte. Er mag wie eine närrische alte Krähe scheinen, die sich nur für ihre Bücher interessiert, aber wir brauchen ihn.\n\nUnter der einzelnen Spitze im Terokkversteck ziehen dunkle Schatten auf. Reshad muss sicher dorthin gelangen.\n\nAuf dem Weg werdet Ihr mit Illusionszaubern versehene Amulette finden. Wenn Ihr sie berührt, verleihen sie Euch Reshads Gestalt.\n\nDie Assassinen der Jünger suchen nach einem alten Ausgestoßenen mit Schriftrollen auf dem Rücken und werden sich so täuschen lassen.\n\nWenn der Zauber schwindet, werden sie ziemlich überrascht sein! Kroar-har-har!", sourceObjective = "Benutzt 5 Illusionszauber, um Sturzschwingen der Jünger hervorzulocken.", completion = "Wie überaus edel von Euch, als Köder für mich herzuhalten. Das werde ich Euch nicht vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34758] = { id = 34758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Hilfe", description = "Wir ha'm hier 'nen passenden Angelplatz, aber kein Köder scheint zu funktionier'n! Wir brauch'n jemanden, der sich mit den Fischen in dieser Gegend auskennt. Geht nach Südost'n und seht mal nach, ob Ihr jemanden an der Küste auftreib'n könnt.", sourceObjective = "Findet einen ortskundigen Fischer, der uns zur Seite stehen kann.", completion = "Jetzt könnt Ihr zeigen, wie nützlich Ihr seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[34760] = { id = 34760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Kriegstruhe von Kull'krosh" }
quests[34761] = { id = 34761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Achtung, Schock!", description = "Oh, bei der heiligen Gnomfaltigkeit!\n\nDer Genussbot 8000 ist kaputtgegangen, bevor er mir auch nur einen einzigen Draenortrüffel bringen konnte. Er ist hierhergeschwommen und hat dabei einen netten kleinen Kurzschluss im Energiefluktuator ausgelöst!\n\nSCHON WIEDER!\n\nIch füttere ihn von hier aus mit Energie, aber sie reicht nicht aus, um den Fluktuator zu überbrücken. Könntet Ihr mir die Blasen der Zitteraale im See bringen? Ich glaube, die wären genau das Richtige!", sourceObjective = "Sammelt 6 Blitzbeutel von Seegrundschockern in Talador.", progress = "Habt Ihr die Aalbeutel?", completion = "Die sehen perfekt aus! Bei allem, was mechanisch ist, das sollte jetzt aber echt funktionieren.\n\nAlso, dann schieben wir die einfach mal hier rein...", sourceObjectiveStatus = "unverified-source-field" }
quests[34765] = { id = 34765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Höhle von Skog", description = "Also, diese Gronnplage beseitigt sich nicht von allein. Ihr werdet ihnen auf hordische Art zeigen müssen, wer hier der Boss ist!\n\nBei den vielen Gronnlingen, die hier herumrennen, muss irgendwo auch ein dickes Mamagronn sein. Findet ihn... es... sie... oder was auch immer, und macht es kalt, dann verliert der Rest dieser Gronnlinge vielleicht das Interesse an unserer kleinen Operation hier.", sourceObjective = "Tötet Skog.", progress = "Habt Ihr das große Mädel gefunden? Oder den Kerl? Oder Gronn? Ehrlich gesagt hab' ich keine Ahnung, wie man die nennen soll.", completion = "Kaum einer weiß, dass der Boden in alten Gronngrotten sich ideal für die Landwirtschaft eignet.", sourceObjectiveStatus = "unverified-source-field" }
quests[34766] = { id = 34766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Logistischer Alptraum", description = "Kommandant, ich fürchte, ich habe... beunruhigende Neuigkeiten.\n\nDiese Saberon folgten uns seit Gorgrond. Sie stehlen unsere Vorräte, durchwühlen unsere Aufzeichnungen und töten unsere Peons!\n\nIch bitte Euch sehr ungern um Eure Hilfe, aber all unsere Soldaten müssen das Lager vor weiteren Überfällen schützen. Wir brauchen diese Vorräte wirklich dringend, ansonsten können wir Euren Willen nicht durchsetzen!", sourceObjective = "Holt 5 Säcke mit Vorräten und 5 Garnisonsaufzeichnungen wieder zurück.", progress = "Kommandant! Hattet Ihr Zeit, unsere Vorräte und Aufzeichnungen zu finden?", completion = "Ich habe nicht einen Moment lang an Euch gezweifelt. Ihr seid ein wahrer Anführer.\n\nLok'tar Ogar!", sourceObjectiveStatus = "unverified-source-field" }
quests[34769] = { id = 34769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Qual der Wahl", description = "Wir sind bereit, loszulegen. Ihr müsst nur noch entscheiden.\n\nSeht Euch die Pläne auf dem Zeichentisch an.\n\nBauen wir einen Pferch oder ein Panzerwerk?", sourceObjective = "Benutzt den Zeichentisch, um Euch zwischen dem Bau eines Pferchs und eines Panzerwerks zu entscheiden.", completion = "Dies ist ein großer Moment, Kommandant. Ich werde Thaelin und seine Leute anweisen, sofort mit der Arbeit zu beginnen.\n\nIhr werdet sehen, dass Eure Entscheidung uns maßgeblich dabei helfen wird, den Kriegshymnenklan zu besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34770] = { id = 34770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ehre eines Klingenmeisters", sourceObjective = "Ich habe keinen Klan. Die Brennende Klinge ist für mich gestorben. Vielleicht werde ich eines Tages meinen eigenen Klan gründen.\n\nIn der Zwischenzeit wäre es mir eine Ehre, an Eurer Seite zu kämpfen. Ihr habt mich befreit und gut gekämpft.\n\nWir können viel voneinander lernen. Was meint Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[34771] = { id = 34771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutes Zeug" }
quests[34772] = { id = 34772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morkeths Käfig" }
quests[34773] = { id = 34773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warum ist das Gebräu verschwunden?", description = "Kommandant, wir haben hier ein kleines... äh... Problem.\n\nDiese Gruppe Saberon ist uns aus Gorgrond gefolgt. Sie stehlen die Schwerter unserer Fußsoldaten und schlachten unsere Bauern ab!\n\nIch bitte Euch nur ungern um Eure Hilfe, aber alle unsere Männer müssen das Lager vor weiteren Überfällen schützen. Außerdem...\n\n<Rüstmeisterin O'Riley senkt ihre Stimme zu einem Flüstern.>\n\nDas Bier haben sie auch mitgenommen!", sourceObjective = "Beschafft 5 Langschwerter von Fußsoldaten und 5 Donnerbräufässer.", progress = "Kommandant! Hattet Ihr schon Zeit, Euch der Saberon anzunehmen?", completion = "Dem Himmel sei Dank! Ich wusste, dass Ihr es schaffen würdet!\n\nZu Diensten, wie immer.", sourceObjectiveStatus = "unverified-source-field" }
quests[34774] = { id = 34774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blingtron 5000", sourceObjective = "Ihr werdet dieses Geschenk annehmen und es wird Euch gefallen. Solltet Ihr das nicht tun, werden automatisch meine organischen Einäscherungswaffen aktiviert. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[34775] = { id = 34775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission wahrscheinlich", description = "Obwohl er in letzter Zeit öfter in Gefangenschaft zu geraten scheint, ist Olin Umberfell doch ein Tauren, der zu kämpfen weiß. In jedem Fall hat er offensichtlich gelernt, wie man die Aufmerksamkeit des Gegners auf sich zieht.\n\nIch habe eine Mission, die ihm wie auf den Leib geschnitten sein dürfte.\n\nWenn Ihr bereit seid, dann erteilt einfach den Befehl über den Befehlstisch vor mir und wir werden ihn unverzüglich aussenden.", sourceObjective = "Schickt Olin Umberfell über den Befehlstisch auf eine Mission.", progress = "Kommandant, Ich habe eine Mission, die für Euren neuen Anhänger ideal wäre.", completion = "Sobald ich von zusätzlichen Missionen erfahre, werde ich sie hier aufführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34776] = { id = 34776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torwächter von Auchindoun", description = "Ich wurde von der Eisernen Horde gefangen genommen, als sie unsere Karawane auf dem Weg nach Auchindoun überfiel.\n\nIch konnte fliehen, doch diese Geister wollen mich nicht zum Sonnenschwur durchlassen, bis sie jemand im Kampf besiegt hat!\n\nBitte, werdet Ihr mir helfen, sie zu besiegen?", sourceObjective = "Besiegt Verteidiger Dalu und Seelenbinderin Halaari im Kampf.", completion = "Vielen Dank, {name}. Ich stehe wirklich in Eurer Schuld.\n\nWenn ich meine Pflichten Lady Liadrin gegenüber erfüllt habe, werde ich Euch aufsuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34777] = { id = 34777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torwächter von Auchindoun", description = "<Fremder/Fremde>, Auchindoun wird angegriffen und ich will bei der Verteidigung helfen.\n\nMein einziges Problem ist, dass ich nur die alte Rüstung meines Großvaters finden konnte. Sie reicht nicht aus, um die Geister zu besiegen, die den Weg nach Auchindoun versperren.\n\nWürdet Ihr sie besiegen und mit mir zusammen das Tor durchqueren? Ich finde bestimmt ein Möglichkeit, wie ich Euch dafür entlohnen kann!", sourceObjective = "Besiegt Verteidiger Dalu und Seelenbinderin Halaari.", completion = "Ich bin Euch auf ewig zu Dank verpflichtet. Eines Tages werde ich einen Weg finden, mich erkenntlich zu zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34778] = { id = 34778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wandernde Arbeiter", description = "{name}, immer mehr Rekruten kommen zu Eurer Garnison. Wir haben bald keine Nahrung mehr.\n\nIch bin mit Exarch Akama in Kontakt getreten, um eventuell Verpflegung aus Elodor zu erhalten, der Kornkammer dieses Tals. Er hat zugestimmt, falls wir dafür bei der Ernte helfen. Damit gewinnen alle.\n\nFalls Ihr meinem Plan zustimmt, sprecht mit Vorarbeiter Surrzisch hier im Hof – er hat verfügbare Arbeiter zusammengetrommelt. Akama und ich werden sie eskortieren und Euch in Elodor weit im Osten treffen!", sourceObjective = "Sprecht mit Vorarbeiter Surrzisch in Eurer Garnison und trefft Euch dann mit den Arbeitern außerhalb von Elodor.", completion = "Ihr habt es geschafft!\n\nAber... einer unserer Wagen leider nicht. Habt Ihr Maraad gesehen? Er ist immer noch irgendwo da draußen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34779] = { id = 34779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet den Wagen", description = "Einer unserer Wagen ist zurückgefallen und irgendwo in den Wäldern im Nordwesten verschwunden. Verteidiger Maraad und einige Eurer Arbeiter sind dort gestrandet.\n\nFindet sie und bringt sie zurück!", sourceObjective = "Findet Maraad und die verschollenen Arbeiter und kehrt mit ihnen in die Elodorfelder zurück.", completion = "Ich behalte die Sicheln. Sie erinnern mich an etwas, das so viele von uns Draenei fast vergessen haben – nämlich, dass das Licht den Bauern genauso erleuchtet wie den Priester.\n\nIhr versteht zu kämpfen. Ich bin froh, Euch einen Freund nennen zu dürfen. Eure Arbeiter werden hier in Elodor sicher sein. Wenn Ihr noch nicht überzeugt seid, dann sprecht mit Exarch Hataaru. Seine Gerätschaften sorgen für die Sicherheit aller Draeneistellungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34780] = { id = 34780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsichtbares Bollwerk", description = "Exarch Akama ist zu zögerlich. Wir können die Bedrohung durch den Schattenmondklan nicht einfach ignorieren. Gut also, dass Ihr da seid!\n\nSeit unserer Ankunft auf Draenor habe ich mich damit beschäftigt, die Technologie, die wir hinterlassen haben, neu zu entwickeln. Dieses große Gebilde hier ist ein Schutzschild. Damit sollten wir die Angriffe des Schattenmondklans abwehren können – wenn wir denn ausreichend Energie dafür haben!\n\nIn meiner Werkstatt im Süden habe ich einige Resonanzkristalle vorbereitet. Bringt jeweils einen Kristall zu den drei Pylonen, die den Schild umgeben und aktiviert sie dann über die Konsole in der Nähe!", sourceObjective = "Bringt die aufgeladenen Resonanzkristalle zum Primär-, Sekundär- und Tertiärpylonen.", progress = "<Die Konsole vibriert vor Energie. Ihr versteht die Anzeige auf dem Bildschirm nicht, aber einige der Lichter blinken Euch noch aufmerksamkeitsheischend an.>", completion = "Die Konsole vibriert vor Energie und die Lichter leuchten auf, als Ihr Euch nähert. Sie scheint Eure Gegenwart zu spüren. Durch einfaches Berühren der Hauptarmatur wird der Kristall draußen zum Leben erweckt.\n\nWenn Hataaru eine solche Technologie aus ein paar Ersatzteilen zusammenbasteln konnte, könnt Ihr Euch die Pracht der Welt, aus der er stammt, kaum vorstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34781] = { id = 34781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defenestrationen", description = "Kaum wird der Kristall mit Energie gefüllt, hört Ihr aus der Ferne Kriegsgeschrei und alarmierte Rufe. Elodor wird angegriffen!\n\nWenn Ihr wollt, dass Eure Arbeiter in einem Stück nach Hause zurückkehren, solltet Ihr bei der Verteidigung der Stadt helfen. Haltet die Invasion auf und kehrt dann zur Steuerkonsole zurück, um die Verteidigung zurückzusetzen.", sourceObjective = "Tötet 8 Räuber oder Dunkelpriesterinnen des Schattenmondklans.", progress = "DerKampfeslärm draußen ist immer noch zu hören. Das ist alarmierend, wenn man bedenkt, dass die Konsole ein wahres Feuerwerk von Warnleuchten anzeigt.", completion = "Ihr habt die Stadt gerettet! Die Konsole deaktiviert sich zwar, als Ihr Euch nähert, aber viele der Anzeigen blinken immer noch hektisch auf. Irgendetwas stimmt nicht.\n\nHataaru ruft Euch zu, um Euch auf etwas draußen aufmerksam zu machen...", sourceObjectiveStatus = "unverified-source-field" }
quests[34782] = { id = 34782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Exarchenrat", description = "Gute Arbeit an den Toren! Die Schattenmondorcs wollten aus irgendeinem Grund Gefangene machen. Ihre Aggressivität spielt uns in die Hände.\n\nKommt mit. Ich möchte Euch dem Exarchenrat vorstellen. Er nennt sich \"Die Hand des Propheten\". Ich habe versucht, die Exarchen zu überzeugen, uns zu unterstützen und gegen die Eiserne Horde in die Offensive zu gehen, aber sie sind zu vorsichtig und reagieren nur langsam... wie immer.\n\nKommt mit, ich werde Euch Exarch Othaar oben auf dem Hügel vorstellen. Vielleicht kann ein Treffen mit <einem Helden/einer Heldin> der Allianz den Rat umstimmen.", sourceObjective = "Sprecht mit Exarch Othaar in Elodor.", completion = "<Exarch Othaar ist eine riesige, furchteinflößende Gestalt. Seine Augen bohren sich förmlich in die Euren, um herauszufinden, ob Ihr Freund oder Feind seid.>\n\nSo, Ihr seid also {name}, edler {class} dieser \"Allianz\", die kürzlich an unseren Küsten aufgetaucht ist. Im Namen des Exarchenrates heiße ich Euch in Elodor willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34783] = { id = 34783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naielle, die Rangari", description = "Ich werde den Exarchenrat zusammenrufen, damit er Euer Gesuch anhört. Niemand von uns zweifelt daran, dass diese \"Eiserne Horde\" eine Bedrohung darstellt, doch nur wenige sind sich einig, was wir ihretwegen unternehmen sollen. Es liegt an Euch und Verteidiger Maraad, die Exarchen zu einen.\n\nExarchin Naielle ist die Anführerin der Rangari, der \"Augen des Propheten\". Sie sind die Späher, die leise die entferntesten Gebiete von Draenor erkunden. Sucht sie in der Enklave der Rangari nordwestlich von hier auf.", sourceObjective = "Sprecht mit Exarchin Naielle in der Enklave der Rangari.", completion = "{name}! Ihr seid gerade erst angekommen, aber ganz Elodor spricht schon von Euch.\n\nIch werde Euer Anliegen beim Exarchenrat sehr gern unterstützen. Ich war schon immer der Meinung, dass wir Draenei uns mehr um die Belange dieser Welt kümmern sollten, anstatt uns nur hinter diesen Mauern zu verstecken.\n\nAber zunächst benötige ich Eure Hilfe...", sourceObjectiveStatus = "unverified-source-field" }
quests[34784] = { id = 34784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spaß mit Fungus", description = "Als Rangari ist es unsere Aufgabe, diese Welt zu erkunden und zu verstehen. Ihr seid hier in Umbrafenn. Viele Draenei sind ums Leben gekommen, als wir diesen Ort entdeckten. Die unbeständigen Sporen bersten, sobald man sich ihnen näherte.\n\nDoch wir beobachteten sie... und lernten.\n\nIn der Umgebung des Sumpfes werdet Ihr auf \"Schimmerpilze\" stoßen, die Ihr an ihren orange leuchtenden Hüten erkennt. Ihr Staub macht Euch unsichtbar für die unbeständigen Sporen. Greift Euch die Sporen – aber sachte! Bringt sie dann zu mir.\n\nWir werden diese Wildnis als Waffe nutzen.", sourceObjective = "Verwendet die Schimmerpilze zu Eurem Schutz, um 12 unbeständige Sporen zu sammeln.", completion = "Schön vorsichtig damit... Gebt sie mir einfach. Wundervoll!\n\nIch werde meine Rangari damit beauftragen, sie in der ganzen Gegend von Elodor zu vergraben. Wenn die Schattenmondorcs einen erneuten Angriff wagen, wartet eine böse Überraschung auf sie!\n\nDraenor ist eine lebensfeindliche Welt. Aber wenn wir uns die Zeit nehmen, um sie zu studieren und zu verstehen, können wir sie zu unserem Vorteil nutzen.\n\nIch werde hier alles bereit machen und treffe Euch dann bald beim Exarchenrat. Ich werde Euren Antrag auf jeden Fall unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34785] = { id = 34785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hataaru, der Konstrukteur", description = "Ihr müsst für mich außerdem Exarch Hataaru aufsuchen. So wie ich das verstehe, habt Ihr ihm bei der Verteidigung des Tors geholfen.\n\nHataaru ist unser Chefkonstrukteur: Er versteht unsere Technologien besser als jeder andere und er hat unermüdlich daran gearbeitet, den Ruhm der Zivilisation, die wir zurückgelassen haben, neu zu erschaffen.\n\nEr hat sich an seinen Arbeitsplatz außerhalb der Ausgrabungsstätte von Elodor etwas südöstlich von hier zurückgezogen. Dort befindet sich unsere Kristallmine. Haltet am Mineneingang Ausschau nach ihm.", sourceObjective = "Sprecht mit Exarch Hataaru außerhalb der Grabung von Elodor.", completion = "Ah, {name}! Ich hatte schon damit gerechnet, Euch wiederzusehen.\n\nIch bin bereit, für Eure Sache beim Exarchenrat einzutreten, aber jetzt liegt gerade ein Notfall vor...", sourceObjectiveStatus = "unverified-source-field" }
quests[34786] = { id = 34786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vollgefressener Goren", description = "Ihr müsst <dieser/diese:c> {class} sein, <der/die:c> Exarch Hataaru so beeindruckt hat. Könnt Ihr uns helfen?\n\nDirekt hinter mir liegt die Grabung von Elodor, die von seltsamen Steinwesen überrannt wurde. Diese sogenannten Goren verschlingen tatsächlich Mineralien, wandeln sie um und lassen kristalline Gebilde aus ihren Armen und Rücken sprießen. Wie die meisten anderen Wildtiere dieser Welt sind auch sie für uns vollkommen rätselhaft.\n\nTötet bitte so viele von ihnen, wie Ihr könnt, und bringt ihre Kristallschuppen zu mir. Ihr werdet damit unsere Erdarbeiter beschützen und gleichzeitig unserer Forschung einen großen Dienst erweisen.", progress = "Wie ist die Lage in der Grabungsstätte?", completion = "<Der Konstrukteur zieht eine Schleife zurück und starrt die Schuppen, die Ihr ihm gebracht habt, konzentriert an.>\n\nDas ist unglaublich. Die Kristallmatrix ist makellos, als sei sie in einer unserer Schmieden auf Argus gefertigt worden.\n\nIch wünschte, wir könnten diese Kreaturen an unsere Maschinen anschließen... doch ich glaube, der Exarch hätte dagegen etwas einzuwenden.\n\nVielen Dank für Eure Hilfe!" }
quests[34787] = { id = 34787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exarch Maladaar", description = "Der Rat ist fast versammelt: Othaar, meine Wenigkeit, Hataaru und Naielle sind bereit. Nur Exarch Maladaar fehlt noch. Seit er aus der Gefangenschaft bei der Eisernen Horde zurückgekehrt ist, ist er wie ausgewechselt... doch Verteidiger Maraad konnte ihn aufspüren.\n\nSucht Maladaar an der Feenlandung gleich südlich des Stadtzentrums.", sourceObjective = "Sprecht mit Exarch Maladaar an der Feenlandung südlich von Elodor.", completion = "{name}, mein Allianzfreund aus Tanaan! Ich habe nicht vergessen, dass ich in Eurer Schuld stehe.\n\nIch werde alles dafür tun, um den Rat zu überzeugen, Euch auf jede erdenkliche Weise zu unterstützen. Allerdings...\n\n\n\nIch mache mir große Sorgen um unsere Sicherheit hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[34788] = { id = 34788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund der Exarchen", description = "Nun bleiben dem Rat der Exarchen nur noch drei Mitglieder. Dennoch, wir stehen tief in Eurer Schuld. Unser Beschluss ist einstimmig: Eure Allianz kann sich unserer vollen Unterstützung auf Draenor versichert sein.\n\nWir werden einen Vertreter der Draenei Eurem direkten Befehl unterstellen. Wir haben hier im Hof drei potenzielle Kandidaten für Euch. Sprecht mit ihnen und wählt, wen Ihr für richtig haltet – wir werden ihn oder sie dann umgehend zu Eurer Garnison entsenden!", sourceObjective = "Wählt einen Anhänger oder eine Anhängerin (entweder Andren, Chel oder Onaala) und sprecht dann mit Exarchin Naielle.", progress = "Wen werdet Ihr wählen, {name}?", completion = "Eine hervorragende Wahl! Wir werden Euren Schützling sofort zu Eurer Garnison entsenden, damit Ihr bei den vor Euch liegenden Missionen die nötige Unterstützung habt.\n\nSprechen wir jetzt über die von Euch beantragten Vorräte...", sourceObjectiveStatus = "unverified-source-field" }
quests[34789] = { id = 34789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecher für die Toten", description = "Jemand aus unseren Reihen hat uns verraten. Anders lässt es sich nicht erklären. Die Exarchen vertrauen einander nicht mehr – und besonders mir nicht. Aber Othaars und Akamas Gesetze sind mir gleich. Wir müssen den Verräter entlarven, und dies können wir nur, indem wir Zwiesprache mit dem Leichnam halten!\n\nStoßt vor dem Altar der Sha'tar auf den östlichen Klippen zu mir. Seelenbinderin Nyami und ich werden einen Exorzismus durchführen, um Hataarus unsterbliche Seele zu retten... und dabei vielleicht in Erfahrung bringen, wer ihm dies angetan hat.\n\nVertraut Ihr mir, {name}?", sourceObjective = "Trefft Exarch Maladaar auf den Klippen östlich des Altars der Sha'tar im Schattenmondtal. Führt an Hataarus Leichnam das Läuterungsritual durch und befragt ihn.", progress = "Einen solchen Tod hat Exarch Hataaru nicht verdient.", completion = "Einer der fünf Exarchen ist tot. Ein anderer ist ein Verräter. Dies sind dunkle Zeiten.\n\nWir werden diese Sache hier und jetzt zu Ende bringen. Kann ich bei dieser letzten Aufgabe auf Euch zählen?", sourceObjectiveStatus = "unverified-source-field" }
quests[34790] = { id = 34790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hieb- und stachelfest", description = "Die Exarchen scheinen Euch zu vertrauen, {class}. Wollt Ihr in den Umbrafenn aufbrechen?\n\nDie Sporensegler dieser Gegend sind für gewöhnlich zahm, doch irgendetwas muss sie plötzlich aufgebracht haben. Wenn sie angreifen, wickeln sich ihre Stachel um alle entblößten Gliedmaßen. Ich habe sie schon verstärktes Leder wie Papier zerreißen sehen. Ich frage mich, wie sie das nur machen?\n\nKönntet Ihr mir wohl ein makelloses Exemplar eines Sporenseglerstachels bringen? Ich würde es gern untersuchen.", sourceObjective = "Besorgt einen makellosen Sporenseglerstachel von einem Mondscheinsegler.", progress = "Die meisten Draenei meiden Umbrafenn. Aber wir Rangari scheinen uns zu den gefährlichsten Orten hingezogen zu fühlen. Dort lernt man jedenfalls, wie die Welt wirklich funktioniert.", completion = "Jetzt schau sich das mal einer an! Das ganze Tentakel ist mit Stacheln übersät. Bäh. Kein Wunder, dass sich die Wunden immer entzünden, die es verursacht. Aber wir können etwas daraus lernen. Ich frage mich, ob die Forscher der Rangari sich vielleicht selbst mit Peitschen ausstatten sollten?\n\nIch danke Euch, {name}. Eure so genannte Allianz muss ja eine wahre Ansammlung von Helden sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[34791] = { id = 34791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Exarchen warnen", description = "Ihr lasst das Buch in Flammen aufgehen, doch nicht, bevor Ihr seinen Inhalt zur Kenntnis genommen habt. Der dämonische Foliant handelte von der Verzauberung von Waffen mit Teufelsenergie. Es sah ganz so aus, als ginge es darum, die Seele des Opfers zu fesseln.\n\nDie Exarchen müssen gewarnt werden, dass sich Verräter in ihren Reihen befinden! Der Rat sollte sich gerade auf dem Hügel gen Osten zu einem Treffen versammeln.", sourceObjective = "Sprecht mit Exarch Maladaar am Altar der Sha'tar im Schattenmondtal.", completion = "Tot! Exarch Hataaru ist tot! Gerade hat man seinen Leichnam gefunden. Man hat ihn in den Rücken gestochen – mit einer Waffe teuflischen Ursprungs. Sagt mir alles, was Ihr wisst.\n\n<Maladaar nickt, als Ihr ihm Euren Fund beschreibt.>\n\nJa. Die Verräter wollten Hataaru seine Seele rauben. Jemand ist auf etwas aus, das er weiß, tot oder lebendig... Wir müssen sofort handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[34792] = { id = 34792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der wahre Name des Verräters", description = "Wir dürfen dem Verräter keine Gelegenheit geben, sich zu verstecken. Ich habe eine Fokuslinse, die verborgene Teufelsenergie aufleuchten lässt. Wenn man sie an einem erhöhten Ort aufstellen würde, könnte sie gleich einem Leuchtfeuer all jene erleuchten, die den Makel teuflischer Verderbnis in sich tragen.\n\nOben auf der Erhebung des Exarchen im Norden gibt es einen Gebetskreis, der der ideale Ort dafür wäre. Errichtet dort die Fokuslinse, {name}. Wenn Ihr etwas findet, beseitigt es. Stoßt dann unten wieder zu mir.", sourceObjective = "Platziert die Fokuslinse ganz oben auf der Erhebung des Exarchen im Schattenmondtal.", completion = "<Der Exarch hört sich Eure Geschichte an und sein Gesicht verzerrt sich vor Besorgnis, dann vor Trauer und schließlich vor Zorn.>\n\nOthaar ist also vom rechten Weg abgekommen. Er nennt sich jetzt \"Socrethar\". Aber zumindest kennen wir jetzt die Antwort. Ich fürchte, dass er für meine Gefangennahme durch die Eiserne Horde verantwortlich war. Aber es könnte noch weitere Verräter unter uns geben. Ich muss sofort zurück nach Auchindoun und mich um unsere Sicherheit kümmern.\n\nUnd in der Zwischenzeit dürften Euch die Exarchen eine Entscheidung schuldig sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[34793] = { id = 34793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begrüßung der Beschützer der Auchenai" }
quests[34794] = { id = 34794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht nach Nagrand tragen", description = "Gut, Euch zu sehen, <Scheff/Scheffin>.\n\nKriegshäuptling Durotan hat uns angewies'n, einen neuen Außenposten in Nagrand zu bau'n. Ich hab' dafür einige unserer Leute abgestellt.\n\nThrall hat uns bereits benachrichtigt, dass der Außenposten bald fertig is'. Er lässt Euch mitteilen, dass alles für Euch bereit steht.\n\nEs wartet 'n Windreiter auf Euch, mit dem Ihr die aktuelle Karawanenlieferung einhol'n könnt.", sourceObjective = "Sprecht mit Steingardist Brox bei der Karawane in Nagrand.", completion = "Sie haben uns... wie aus dem Nichts... angegriffen.\n\n<Der Steinwächter verliert beinahe das Bewusstsein.>", sourceObjectiveStatus = "unverified-source-field" }
quests[34795] = { id = 34795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Kriegshymnenklans", description = "<Der Offizier leidet unter starken Schmerzen. Es ist offenkundig, dass er nicht mehr lange durchhalten wird.>\n\nDer Kriegshymnenklan. Überraschungsangriff.\n\nAuf dem Weg zur... Brennenden Klinge.\n\n<Er hält kurz inne, bevor er fortfährt.>\n\nSie haben den... Bauplan...\n\n<Dies sind seine letzten Worte.>", sourceObjective = "Sprecht mit Thrall in Wor'var.", completion = "Kommandant {name}, es ist gut, dass Ihr hier seid. Es gibt viel zu besprechen.\n\nDie Situation in Nagrand wird zunehmend brenzliger. Der Kriegshymnenklan hat sich in Bewegung gesetzt.\n\nAls ob das nicht schon genug wäre, hat Grommash Garrosh zu ihrem neuen Kriegsherr ernannt.", sourceObjectiveStatus = "unverified-source-field" }
quests[34801] = { id = 34801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine missglückte Pilgerfahrt", description = "Ich bin ein einfacher Pilger, das schwöre ich. Bitte tut mir nicht weh!\n\nMeine Schwester und ich waren auf dem Weg nach Auchindoun, um meiner Großmutter die letzte Ehre zu erweisen, als unser Wagen einen Stein erwischt hat und wir die Kontrolle verloren haben. Ich habe überlebt, doch meine Schwester...\n\n<Nadur weint.>\n\nBitte, Ihr müsst mir helfen. Ich bin verzweifelt. Wenn Ihr mir etwas Streunerblut, ein paar Löwenmäulchen und ein Flusshüpferauge bringt, könnte ich daraus einen Trank herstellen, der sie zurückbringt. Ich weiß, dass ich das kann...", sourceObjective = "Sammelt 6 Streunerblut, 6 Löwenmäulchenwedel und ein Flusshüpferauge.", progress = "Tuliaa ist nicht nur einfach meine Schwester, sie ist meine beste Freundin.", completion = "Vielen Dank, Fremder.", sourceObjectiveStatus = "unverified-source-field" }
quests[34802] = { id = 34802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine missglückte Pilgerfahrt", description = "Meine Schwester und ich waren auf dem Weg nach Auchindoun, um meiner Großmutter die letzte Ehre zu erweisen, als unser Wagen einen Stein erwischt hat und wir die Kontrolle darüber verloren haben. Ich habe überlebt, doch meine Schwester...\n\n<Nadur weint.>\n\nBitte, Ihr müsst mir helfen. Wenn Ihr mir etwas Streunerblut, ein paar Löwenmäulchen und ein Flusshüpferauge bringt, könnte ich daraus einen Trank herstellen, der sie zurückbringt... Ich weiß einfach, dass ich das kann...", sourceObjective = "Sammelt 6 Streunerblut, 6 Löwenmäulchenwedel und ein Flusshüpferauge.", progress = "Ich weiß nicht, was ich ohne Tuliaa anfangen sollte... Sie ist nicht nur einfach meine Schwester, sie ist meine beste Freundin.", completion = "Ich danke Euch, tausend Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[34803] = { id = 34803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht ihnen Beine!", description = "Eure Späher haben das Alphamännchen der Saberon direkt vor unseren Toren ausgemacht!\n\nWenn wir dieses Ziel ausschalten, wird der Rest des Ungeziefers wieder in ihre Höhlen flüchten.\n\nIch bitte Euch nur ungern um noch mehr, doch Ihr seid <der/die> Einzige, <der/die> dieser Aufgabe gewachsen ist, Kommandant.", sourceObjective = "Tötet Zwingenzahn direkt außerhalb von Vol'jins Stolz.", completion = "Für {name}! Für die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[34804] = { id = 34804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht in meinem Vorgarten", description = "Kommandant, wir haben das Alphatier der Saberon direkt vor unseren Toren gesichtet!\n\nWir glauben, dass sein Tod die anderen mit eingezogenem Schwanz in die Flucht schlagen würde, doch die Bestie ist wirklich riesig!\n\nIch bitte Euch nur ungern um noch mehr, doch Ihr seid <der/die> Einzige, <der/die> dieser Aufgabe gewachsen ist.", sourceObjective = "Tötet Darmreißer direkt außerhalb von Fort Wrynn.", completion = "Sieg! Für die Allianz!", sourceObjectiveStatus = "unverified-source-field" }
quests[34805] = { id = 34805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echojäger", description = "Ich bin kein Magier, aber ich habe mit der Zeit einige Zauber erlernt – genug, um mich unentdeckt bewegen zu können.\n\nLeider benutzen die Vampirfledermäuse in diesen Wäldern ihre Augen nicht. Sie werden das Rascheln meiner Robe und Percys unaufhörliches Gackern schon von weitem hören.\n\nKönntet Ihr sie für mich aus dem Weg räumen?", sourceObjective = "Tötet 10 Echojäger.", completion = "Verdammte Viecher! Nicht mehr als fliegende Ratten, wenn Ihr mich fragt!", sourceObjectiveStatus = "unverified-source-field" }
quests[34806] = { id = 34806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schotlinge stutzen", description = "Ryans blutüberströmter Leichnam ist an der Höhlenwand zusammengesackt. Der Körper ist von winzigen Bissspuren gezeichnet.\n\nDiese Schotlinge sind ganz eindeutig eine Gefahr für Euch und Eure Garnison.\n\nEs wird Zeit für eine Runde Unkrautvernichtung.", sourceObjective = "Nehmt Rache an den Schotlingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34807] = { id = 34807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Goldmähne der Häuter" }
quests[34808] = { id = 34808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr faule Peons", description = "Wir haben die seltene Gelegenheit, dem Kriegshymnenklan einen schweren Schlag zu versetzen, aber wir benötigen Eure Weisheit und Führung.\n\nDie wichtigste Entscheidung besteht darin, ob wir einen Pferch oder ein Panzerwerk errichten sollen. Diese Wahl wird unsere komplette Herangehensweise an den Konflikt mit dem Kriegshymnenklan beeinflussen.\n\nThazz'ril wird die Bauarbeiten befehligen. Würdet Ihr ihn dabei unterstützen?\n\nAnscheinend hat er Probleme, seine Peons zur Arbeit zu motivieren.", sourceObjective = "Motiviert 8 faule Peons.", completion = "Ich wusste, dass es ein Fehler war, diese Kerle aus dem Tal der Prüfungen mitzubringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34809] = { id = 34809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lektion in Mineralogie", description = "<Gazmolf gestikuliert in Richtung der großen Maschine.>\n\nIch habe diese Maschine konstruiert, um Elementiummineralien in ihre Grundbestandteile zu zerlegen. Wisst Ihr, es ist nicht nur das im Boden Vergrabene, das ungemein wertvoll sein kann – sondern auch der Boden selbst!\n\nSeht Euch nur die Erdelementare dort unten an: Im Inneren jedes einzelnen steckt ein irdener Kern, der voll von Edelmetallen ist!\n\nDiese Elementare werden uns reich machen! Sammelt ein paar irdene Kerne, platziert sie in der Gold-o-matik 9000 und Ihr werdet einen fairen Anteil erhalten!", sourceObjective = "Sammelt 4 irdene Kerne.", progress = "<Die Gold-o-matik 9000 zischt und surrt wie schweres Gerät vor sich hin.>", completion = "<Die Gold-o-matik 9000 zerknirscht und zermalmt die Überreste der Elementare.>\n\nKnack-knack-tschack, Tschack-knacktschak-knack...", sourceObjectiveStatus = "unverified-source-field" }
quests[34810] = { id = 34810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gazmolf Futzwangler und der allerletzte Kreuzzug", description = "Ich bin hier in Nagrand, um Interessierte für die Werterhaltungsgesellschaft des Dampfdruckkartells anzuwerben. Wir repräsentieren die archäologische Abteilung des Dampfdruckkartells.\n\nWir streben an, sämtliche Relikte, Antiquitäten und Kuriositäten zu sammeln, die Nagrand zu bieten hat! Wir suchen derzeit Feldmesser, Ausgräber, Abenteurer... und was es sonst noch alles gibt!\n\nWenn Ihr Euch nicht davor scheut, Euch die Hände schmutzig zu machen, sprecht mit Gazmolf Futzwangler drüben in der Steinschlagsenke. Er ist der für diese Expedition verantwortliche Goblin!", sourceObjective = "Sprecht mit Gazmolf Futzwangler.", completion = "Schön zu sehen, dass noch Interesse an wahrer Archäologie besteht!\n\nViele haben einen falschen Begriff davon, worum es bei der Archäologie wirklich geht, aber keine Angst! Der große und berühmte Gazmolf Futzwangler ist da, um es Euch zu lehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[34811] = { id = 34811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutes Personal ist schwer zu finden", description = "Das Ausgrabungsteam streikt!\n\nVorarbeiter Thazwix und seine Kumpanen denken, dass sie die Werterhaltungsgesellschaft des Dampfdruckkartells um etwas Extraknete erpressen können, indem sie die Arbeit niederlegen.\n\nWas ich brauche, ist ein Streikbrecher. Jemand, der diese Kerle unter Druck setzt, indem er die Arbeit erledigt, die sie liegen lassen!\n\nGeht runter in die Schlucht, grabt ein paar Antiquitäten für mich aus und ich werde Euch das Gehalt zahlen, das diese faulen Hunde ansonsten bekommen hätten!", sourceObjective = "Sammelt 8 Antiquitäten aus Nagrand.", progress = "Habt Ihr die Antiquitäten aus Nagrand?", completion = "Gute Arbeit, {name}!\n\nDieser Haufen Faulpelze kam sofort angekrochen, als sie herausgefunden haben, dass jemand anderes ihr Geld verdient! Ich glaube nicht, dass Thazwix oder seine Kumpanen von jetzt an noch viel Ärger machen werden.\n\nHier, wie versprochen – Euer Gehalt für getane Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[34812] = { id = 34812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hordeställe Verfolgungsereignis" }
quests[34813] = { id = 34813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hordewerkstatt Verfolgungsereignis" }
quests[34814] = { id = 34814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bekanntschaften machen", description = "Es ist schön zu sehen, dass jemand anderes auch ein Interesse an den arkanen Künsten hegt. Das kommt dieser Tage viel zu selten vor, wenn Ihr mich fragt!\n\nUnglücklicherweise muss ich mich mit Cordana treffen, um eine wichtige Sache zu erledigen, aber wir haben Glück! Ein guter Freund bei den Kirin Tor hat sich bereit erklärt, Euch dabei zu helfen, das arkane Sanktum mit dem Leyliniennetz zu verbinden.\n\nEr wartet bei meinem Turm. Lasst uns sofort dorthin aufbrechen, damit Ihr Euch kennenlernen könnt.", sourceObjective = "Folgt Erzmagier Khadgar und sprecht mit Magister Krelas in Zangarra.", completion = "Ich bin Magister Krelas, Pyromane.\n\nDie Freude ist ganz meinerseits.", sourceObjectiveStatus = "unverified-source-field" }
quests[34815] = { id = 34815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bekanntschaften machen", description = "Es ist schön zu sehen, dass jemand anderes auch ein Interesse an den arkanen Künsten hegt. Das kommt dieser Tage viel zu selten vor, wenn Ihr mich fragt!\n\nUnglücklicherweise muss ich mich mit Cordana treffen, um eine wichtige Sache zu erledigen, aber wir haben Glück! Eine gute Freundin bei den Kirin Tor hat sich bereit erklärt, Euch dabei zu helfen, das arkane Sanktum mit dem Leyliniennetz zu verbinden.\n\nSie wartet bei meinem Turm. Lasst uns sofort dorthin aufbrechen, damit Ihr Euch kennenlernen könnt.", sourceObjective = "Folgt Erzmagier Khadgar und sprecht mit Magistra Serena in Zangarra.", completion = "Eine Freude, Eure Bekanntschaft zu machen.\n\nIch bin Magistra Serena, Frostmagierin der Extraklasse!", sourceObjectiveStatus = "unverified-source-field" }
quests[34817] = { id = 34817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger am Altar", description = "Rettet die Gefangenen vom Altar.\n\n[NOTE: THIS QUEST WILL GET SIGNIFICANT REVAMP ONCE WE GET THE ALTAR IN]" }
quests[34818] = { id = 34818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Man nennt ihn Lantresor von der Klinge", description = "Als der Kriegshymnenklan Eure Karawane überfiel, wurden die Garnisonsbaupläne zum Dorf der Brennenden Klinge gebracht. Ohne die Pläne kann ich das Gebäude nicht erbauen.\n\nEs gibt Gerüchte über einen jungen Klingenmeister, der vor vielen Jahren aus dem Klan verstoßen wurde. Sie nennen ihn Lantresor von der Klinge.\n\nUnsere Späher sahen ihn kürzlich nach Hallvalor zurückkehren, um die führenden Klingenmeister herauszufordern. Doch sie haben ihn in Ketten gelegt.\n\nVielleicht ist er noch am Leben und hilft Euch sogar dabei, die Pläne wiederzubeschaffen.", sourceObjective = "Findet Lantresor von der Klinge in Hallvalor.", completion = "Wer seid Ihr?\n\nErkennt Ihr den Tod nicht, wenn Ihr Ihn seht, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[34819] = { id = 34819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein fruchtbares Unterfangen", description = "Oh, nein! Sie sind wohl Vegetarier.\n\nDiese Elekks brauchen Früchte, und zwar eine Menge. Hier unter den Bäumen gibt es überall eine Menge Kirschen.\n\nEs macht Euch doch nichts aus, mir ein paar mitzubringen, oder?", sourceObjective = "Sammelt 15 Nagrandkirschen.", progress = "Ich habe die fürchterlichsten Gerüchte gehört, wie man an diese Dinger gelangt.\n\nJemand hat mir gesagt, dass sie zunächst von den Talbuks gefressen und dann \"weiterverarbeitet\" würden und dann... Aber ich möchte gar nicht darüber sprechen.", completion = "Habt Ihr sie alle? Ich weiß einfach, dass das funktionieren wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[34820] = { id = 34820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisste Holzfäller", description = "Shelly und ihr Trupp sind immer noch nicht aus dem Schummergehölz zurückgekehrt.\n\nSie sind schon seit Tagen überfällig... Ich hoffe, dass bei ihnen alles in Ordnung ist.", sourceObjective = "Findet heraus, was Shelly und den vermissten Holzfällern widerfahren ist.", completion = "Dies ist einer der Lastmaulesel, die Shelly und ihr Trupp mit zum Schummergehölz genommen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[34821] = { id = 34821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschwörung von Khadgar" }
quests[34822] = { id = 34822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was wir brauchen", description = "Mir ist zu Ohren gekommen, dass Ihr auf dem Weg aus Tanaan ein Schiff gekapert habt und damit auf Grund gelaufen seid.\n\nWie mein Vater immer sagte: Das Wrack des Einen ist des andern Goblins Werkstatt.\n\nGeht runter zur Küste westlich der Garnison und seht nach, ob Ihr ein paar wiederverwertbare Materialien finden könnt. Oh, und... passt besser auf. Es sollen Ogerplünderer in der Gegend unterwegs sein.", sourceObjective = "Sammelt 10 Kisten mit Sklavenschiffvorräten.", progress = "Wie geht's mit der Bergungsoperation voran?", completion = "He... das sieht nach gutem Material aus. Über die Eiserne Horde kann man ja sagen, was man will, aber sie arbeiten auf jeden Fall mit hochwertigen Rohstoffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34823] = { id = 34823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es gibt noch Ogrons?", description = "Kommandant, uns're Verbündeten vom Frostwolfklan bericht'n, dass die Oger der Speerspießer westlich von hier einen Außenposten unter dem Befehl eines Ogron hab'n.\n\nIch hab schon Geschichten von diesen Ogron gehört, aber noch keinen geseh'n. Das sind brutale Kreaturen aus einer Zeit, die besser vergessen geblieb'n wäre. Die meisten wurden während der Gründung der ursprünglichen Horde erschlag'n. Was ihnen an Weisheit mangelt, machen sie durch Gewalt, schiere Kraft und Gier wett.\n\nIch rate Euch, diese Kreatur so schnell wie möglich zu beseitigen.", sourceObjective = "Tötet Groog.", progress = "Wo der Ogron wandelt, folgen ihm sicherlich Tod und Verderben.", completion = "Gut gemacht, Scheff. Die Oger der Speerspießer hab'n damit begonn'n, ihre Stoßtrupps zurückzuzieh'n. Ich erwarte allerdings, dass sie zurückkommen werd'n, und zwar in rauh'n Mengen. Um die Bedrohung durch ihre Festung werd'n wir uns bald kümmern müss'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[34824] = { id = 34824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was wir haben", description = "Jede Festung braucht drei Dinge.\n\nErstens: Peons! Findet Skaggit und tragt ihm auf, unsere Peons wieder an die Arbeit zu schicken.\n\nZweitens: Baumaterialien. Die Peons haben für Euch ein Lager aufgestellt, wo in Eurer Abwesenheit gewonnene Ressourcen aufbewahrt werden. Ihr solltet es Euch ansehen.\n\nUnd drittens: rohe Muskelkraft! Garnisonsgebäude zu errichten, kann etwas dauern. Für Euer erstes Gebäude könnten wir aber Skaggits kürzlich beförderten Chefpeon II anheuern, um den Bau zu beschleunigen. Findet ihn und sagt ihm, dass ich Euch geschickt habe.", sourceObjective = "Tragt Skaggit auf, dafür zu sorgen, dass die Peons arbeiten, seht in Euer Garnisonslager und findet Chefpeon II.", completion = "Jo, so muss das aussehen. Holz, Steine, Peons, noch mehr Peons. Ist ja fast, als würden wir Euch eine Festung bauen oder so.", sourceObjectiveStatus = "unverified-source-field" }
quests[34825] = { id = 34825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Gruuk" }
quests[34826] = { id = 34826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Freund meines Feindes", description = "Hallvalor ist die angestammte Heimat des Klans der Brennenden Klinge. Da sie alte Verbündete sind, erlaubte der Kriegshymnenklan den Klingenmeistern, in Nagrand zu verbleiben.\n\nWir sind grimmige Kämpfer, aber wir können nicht gewinnen, wenn die Brennende Klinge uns angreift. Es wäre weise, den Kampf zu ihnen zu tragen.", sourceObjective = "Tötet 15 Truppen der Brennenden Klinge in Hallvalor.", completion = "Ein großer Sieg über den Klan der Brennenden Klinge!\n\nDiese neue Kriegsfürstin, Azuka Klingenwut, scheint eine mächtige Gegnerin zu sein. Wir müssen sie und ihre Klingenmeister im Auge behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[34827] = { id = 34827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Krallenpriester", description = "Krallenpriester leben verborgen unter uns und wachen über die Riten für die Rückkehr des Klauenkönigs.\n\nWir haben durch die Proklamation der Jünger, die Ihr in Skettis an Euch genommen habt, erfahren, dass zwei von ihnen auf der Schattenlichtung im Norden leben. Orcs sind in das Gebiet vorgedrungen, und die Strahlenwaffe der Jünger hat das Akrazversteck in einen rauchenden Krater verwandelt.\n\nWie Ihr seht, bedrängen Feinde mein Volk von allen Seiten.\n\nKrallenpriester Ishaal hat überlebt und versteckt sich. Trinkt dieses Elixier in der Nähe seiner Hütte, um einen Blick in die Schatten zu erhaschen und Verbindung mit ihm aufzunehmen.", sourceObjective = "Trinkt das Elixier der Schatten bei Ishaals Hütte auf der Schattenlichtung.", completion = "Hm, ich habe etwas anderes erwartet, als es hieß, dass Iskar Hilfe schickt.\n\nEgal. Ihr werdet reichen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34828] = { id = 34828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ishaals Kugel", description = "Die Jünger waren hinter mir her, aber ich hatte mich bereits versteckt. Ich beobachtete aus den Schatten heraus, wie sie meine Hütte plünderten.\n\nDann sah ich, wie die Orcs der Zerschmetterten Hand kamen und sie wie Schlachtvieh massakrierten. Scheinbar ist heutzutage jeder hinter uns her.\n\nEiner dieser Orcschläger hat sich mit meiner Seherkugel davongemacht. Ich muss sie unbedingt wiederhaben, wenn ich Iskar irgendwie von Nutzen sein soll.", sourceObjective = "Besorgt Ishaals Kugel aus Dornnarbes Lager.", progress = "Habt Ihr die Kugel gefunden?", completion = "Hmm... Irgendetwas stimmt nicht. Jemand hat sich an ihr zu schaffen gemacht.\n\nJemand anderes hat meine Kugel benutzt, um in die Schatten einzutreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[34829] = { id = 34829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Nachbarn", description = "Der Klan der Zerschmetterten Hand besteht aus Orcs, die kein anderer Klan bei sich dulden würde. Sie sind sadistische Krieger, die ihre eigenen Körper verstümmeln; entweder als Zeichen der Solidarität oder weil sie einfach Spaß an den Schmerzen haben.\n\nDas spielt auch keine Rolle. Wichtig ist, dass sie ihr Gebiet ausweiten und jeden, der ihnen im Weg steht, abschlachten.\n\nWir müssen uns ihrer entledigen.", sourceObjective = "Tötet 15 Orcs der Zerschmetterten Hand in Dornnarbes Lager.", completion = "Blut mit Blut vergolten, wie es sich gehört.", sourceObjectiveStatus = "unverified-source-field" }
quests[34830] = { id = 34830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter dem Schleier", description = "Kurz nachdem die Orcs eingefallen waren, wurde das Akrazversteck von einem Lichtstrahl von der Himmelsnadel verwüstet.\n\n<Ishaals Augen werden glasig, als er in seine Kugel blickt.>\n\nScheinbar haben sie ihr Hauptziel verfehlt. Zellek lebt, versteckt in den Schatten.\n\nUnd... noch jemand. Der Orcassassine, der meine Kugel benutzt hat.\n\nNehmt dies. Trinkt es im Akrazversteck und sucht nach Zellek.\n\nOh, und seid vorsichtig! Es ist etwas wirkungsvoller als beim letzten Mal. Ihr werdet sehen...", sourceObjective = "Trinkt das erhebliche Elixier der Schatten bei Zelleks Hütte im Akrazversteck.", completion = "Nun, Ihr habt mich noch nicht erstochen.\n\nDas ist ein gutes Zeichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34831] = { id = 34831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encounter Mushroom" }
quests[34833] = { id = 34833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urtum stutzen" }
quests[34834] = { id = 34834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allgemeiner Kommentar" }
quests[34835] = { id = 34835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energie sammeln" }
quests[34836] = { id = 34836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondblüten", description = "Wie ich mich danach sehne, Kat'la in meinen Armen zu halten.\n\nKein Stern oder Mond kann sich mit ihrer Schönheit messen.\n\nAber ich bin ja nur ein einfacher Eberbauer.\n\nWenn ich doch nur die Zeit hätte, mir von dieser jämmerlichen Arbeit frei zu nehmen und Kat'la ein paar Mondblüten zu pflücken.\n\nIch würde es niemals wagen, ihr ohne ein ansprechendes Geschenk meine Liebe zu gestehen.", sourceObjective = "Pflückt 5 Mondblüten.", progress = "Wie kann ich Euch helfen, {class}?", completion = "Das sind ja wirklich Mondblüten! Ihr seid wirklich zu freundlich! Ich kann es kaum erwarten, sie Kat'la zu geben!", sourceObjectiveStatus = "unverified-source-field" }
quests[34837] = { id = 34837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besuch bei den Gordunni", description = "Das Arsenal ist jetzt gut mit Jovit versorgt, doch in der Mine ist nicht genug, dass es lange so bleiben wird. Im Süden gibt es einen Berg, der vor dem Zeug nur so überquillt, doch es gibt da ein Problem: Oger!\n\nDie Gordunni leben auf dem Berg und sie haben damit begonnen, Jovit an die Eiserne Horde zu verkaufen.\n\nWir müssen dorthin und uns die Mineralien sichern.\n\nIch packe ein paar Vorräte zusammen, dann treffen wir uns in der Nähe ihrer Festung im Süden.", sourceObjective = "Reist zur Gordalfestung und trefft Euch dort mit Morketh Klingenschrei.", completion = "Bevor wir aufbrachen, habe ich ein paar Dinge hergestellt, die wir vielleicht brauchen können: ein paar Bomben, einen Greifhaken, und ich konnte sogar einen der Goblins dazu bringen, einen Reserveraketenrucksack zu besorgen.\n\nIch bin sicher, wir werden für all diese Dinge Verwendung finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[34838] = { id = 34838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ikkys Ei", description = "<Erstaunlicherweise ist dieses eine Ei nicht den Verheerern zum Opfer gefallen.\n\nJemand hat liebevoll einen kleinen Anhänger um das Ei geschnürt. Darauf steht: \"Ikky\".>", sourceObjective = "Helft Ikky auf der Schattenlichtung dabei, aus dem Kaliriei zu schlüpfen.", completion = "<Das Küken schwingt sich sofort in die Luft und blickt Euch daraufhin erwartungsvoll zwitschernd an.>", sourceObjectiveStatus = "unverified-source-field" }
quests[34839] = { id = 34839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Skog" }
quests[34840] = { id = 34840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bomben werfen", description = "Es führt nur ein einzelner Pfad zur Festung der Gordunni, den sie sogar vor einem Großangriff gut verteidigen können.\n\nZum Glück rechnen sie nicht mit einem Einbruch von zwei Leuten.\n\nDies ist eine großartige Gelegenheit, um ihre Verteidigungsanlagen auszuschalten und unserer Artillerie im Arsenal ein wenig Schießübung zu geben.\n\nNehmt diese Rauchgranaten und nutzt sie, um einen Artillerieschlag auf ihre Katapulte anzufordern, während wir dort hinaufsteigen.", sourceObjective = "Führt Artillerieangriffe auf die Lager der Felswerfer der Gordunni in der Gordalfestung durch.", completion = "Wir sind drin! Es gibt viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[34841] = { id = 34841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Eisbedeckte Vorräte" }
quests[34843] = { id = 34843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Frostfang" }
quests[34844] = { id = 34844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Require More Resources" }
quests[34845] = { id = 34845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die in den Schatten lauern", description = "Es gibt Berichte über Mitglieder des Schattenmondklans, die sich bei den Ruinen an der Küste herumtreiben.\n\nDort halten sich gerne junge Liebespaare auf, um sich den Sternenhimmel anzusehen und sich ihrer Liebe zu versichern.\n\nWie Ihr seht, sind wir kein Dorf voller Krieger.\n\nIch werde Euch gebührend entlohnen, wenn Ihr Euch zu den Ruinen begebt und dafür sorgt, dass die Schattenmondorcs Abstand halten.", sourceObjective = "Tötet Disruptoren des Schattenmondklans.", sourceObjectiveStatus = "unverified-source-field" }
quests[34846] = { id = 34846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischschlacht", description = "Wir haben hier einen leicht zugänglichen Platz zum Angeln, aber unsere Köder scheinen nicht zu funktionieren! Wir müssen einen ortskundigen Fischer finden, der uns helfen kann. Könnt Ihr das erledigen?", sourceObjective = "Findet einen ortskundigen Fischer, der uns zur Seite stehen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[34847] = { id = 34847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbotene Liebe", description = "Mein Sohn, Kral'za, hat einen unglaublichen Dickschädel.\n\nNachdem wir uns vom Schattenmondklan losgesagt haben, weigerte er sich, seine Beziehung mit einer jungen Orcfrau von ihnen zu beenden.\n\nIch habe ihm verboten, sie wiederzusehen, aber heute ist er einfach davongelaufen und noch nicht wieder zurückgekehrt.\n\nIch traue dieser Dol'mak nicht. Sie experimentiert weiterhin mit Leerenmagie herum, genau wie die anderen Mitglieder des Schattenmondklans.", sourceObjective = "Findet Kral'za.", completion = "Aka'Magosh, {class}. Ich wusste, dass diese Leerenhexe nichts taugt.", sourceObjectiveStatus = "unverified-source-field" }
quests[34849] = { id = 34849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klinge selbst", description = "Als sie mich in Ketten legten, hat mir der Ausbilder des Klans der Brennenden Klinge, Luhk der Scharfäugige, meine Klinge abgenommen. Er ist ein ehrenwerter Orc, wenn auch seine Ausbildungstechniken kontraproduktiv sind.\n\nIch will meine Klinge zurück, {class}.", sourceObjective = "Sichert Lantresors Klinge von Ausbilder Luhk.", progress = "Ein Klingenmeister ohne seine Klinge ist überhaupt kein Klingenmeister.", completion = "Wenn Ihr Luhk besiegen könnt, gibt es für Euch vielleicht doch noch Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[34850] = { id = 34850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht ohne meine Ehre", description = "Die Klinge ist nicht der einzige wichtige Gegenstand, den ein Klingenmeister mit sich führt.\n\nSobald er seine letzten Prüfungen in der Höhle der Meister abgeschlossen hat, wird einem Klingenmeister die Ehre gewährt, das Banner der Brennenden Klinge zu tragen.\n\nAls mein Anliegen, meinen rechtmäßigen Platz innerhalb des Klans wieder einzunehmen, auf taube und feige Ohren fiel, wurde ich dieser Ehre beraubt.\n\nOhne Zweifel wird mein Banner irgendwo in Hallvalor verwahrt. Sie werden es einem anderen angehenden Klingenmeister übergeben, wenn sie es nicht vorher verbrennen.", sourceObjective = "Sucht nach dem Banner des Klingenmeisters in einer Truhe der Brennenden Klinge.", progress = "Habt Ihr mein Banner?", completion = "Ich erwarte nicht, dass Ihr die Bedeutung dessen erfasst, was Ihr soeben getan habt.\n\nEines Tages werdet Ihr es vielleicht verstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34851] = { id = 34851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Gruuk", description = "Goren sind gefährlich, besonders in großer Zahl... und erst recht, wenn wir einen blinden, ausgelaugten Schamanen bei uns haben.\n\nGlücklicherweise leben Goren nicht sehr lange. Unglücklicherweise vermehren sie sich aber schnell und wachsen noch schneller.\n\nWenn wir das hier schaffen wollen, müssen wir ihre Brutmutter finden. Wenn wir sie töten und ihre Eier vernichten, sollte das den Ansturm der Goren bremsen. Überprüft die Löcher in der Nähe des Tors zur Schmiede, ich werde sie solange von Drek'Thars Fährte ablenken." }
quests[34855] = { id = 34855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchbruch", description = "Um die Festung zu sichern, müssen wir den Hexenfürsten Morkurk töten, aber noch nicht sofort.\n\nSeine drei Stellvertreter Vorgorsh, Zulmork und Cromaug sind allesamt mächtige Magier, die alle Morkurk gegenüber ausgesprochen loyal sind.\n\nWahrscheinlich werden sie dem Hexenfürsten zu Hilfe eilen, wenn wir ihn direkt angreifen. Schalten wir besser erst sie aus, damit das nicht passieren kann.", sourceObjective = "Tötet Wesir Vorgorsh, Wesir Zulmork und Wesir Cromaug.", completion = "Jetzt da wir die Wesire los sind, wird der ganze Verzauberungshandel der Gordunni mit der Eisernen Horde zusammenbrechen!\n\nNun können wir uns Morkurk zuwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[34856] = { id = 34856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gok Tracking Quest" }
quests[34857] = { id = 34857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suchmarkierung: Orcs aus der Höhle geworfen" }
quests[34858] = { id = 34858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschätztes Plündergut", description = "Die Eiserne Horde hat den Gordunni Duplikate meiner Klingen geschenkt. Aber zu welchem Zweck? Als Zahnstocher!\n\nKlar, die Klingen sind nur minderwertige Kopien, doch es handelt sich immer noch um MEINE Entwürfe und ich kann es nicht ertragen, dass sie sich noch einen Augenblick länger in diesen Ogerpranken befinden!\n\nWenn wir schon mal da sind, könnt Ihr mir einen Gefallen tun und ihnen diese Klingen aus den Händen reißen!", sourceObjective = "Sammelt 6 \"Zahnstocher\" der Gordunni von Knüpplern oder Spaltern der Gordunni in der Gordalfestung.", progress = "Ist es Euch gelungen, alle meine Klingen wieder zurückzubekommen?", completion = "Vielen Dank, Kommandant. Dadurch wurde ein weiterer Fleck auf meiner Ehre getilgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[34859] = { id = 34859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: No'losh" }
quests[34860] = { id = 34860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorratswiederbeschaffung", description = "Wir scheinen gerade rechtzeitig eingetroffen zu sein!\n\nDie Gordunni haben Ausrüstung für die Eiserne Horde verzaubert, und es sieht aus, als hätte diese ihre letzte Lieferung noch nicht abgeholt.\n\nWir könnten dieses Zeug viel besser gebrauchen! Machen wir Jagd auf diese Frachtcontainer. Ich habe ein paar Signalfackeln mitgebracht, mit denen wir sie auf dem Luftweg abtransportieren lassen können, wenn wir sie gesichert haben.", sourceObjective = "Bergt 6 Lieferungen der Eisernen Horde.", completion = "Alles klar, das sollte der letzte von ihnen gewesen sein.\n\nNichts fühlt sich so gut an wie das Wissen, dass man stärker als der Feind ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[34861] = { id = 34861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir brauchen eine Armee", description = "Der neue Kriegshäuptling hat also beschlossen, Euch Kriegsmeister Zog zur Seite zu stellen, um die Operationen hier vor Ort zu leiten. Zog!\n\nIch habe gehört, der Kerl sei berüchtigt dafür, dass er die Allianz UND die Horde vereint hat, um gegen die Silithiden bei den Toren von Ahn'Qiraj zu kämpfen.\n\nDamals war er ein General.\n\nIhr solltet ihm auf jeden Fall davon berichten, dass die Kaserne einsatzbereit ist. Ich bin mir sicher, dass er einige Vorschläge haben wird, wie wir sie gut verwenden können.\n\nIhr findet Zog drüben im Hauptgebäude.", sourceObjective = "Sprecht mit Kriegsmeister Zog.", completion = "Kommandant, es ist mir eine Ehre, Euch zu dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34862] = { id = 34862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Entzündet die Kohlenpfannen" }
quests[34865] = { id = 34865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Skog" }
quests[34866] = { id = 34866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft mich in der Höhle", description = "Es wird Zeit, {class}. Zeit, Euch diesen Bauplan zu verschaffen.\n\nZeit, dass wir uns den Meistern stellen.", sourceObjective = "Trefft Euch mit Lantresor von der Klinge in der Höhle der Meister.", completion = "Ihr habt es geschafft. Sehr gut.\n\nAber hier reinzukommen, war nichts im Vergleich zu dem, was Euch noch erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[34867] = { id = 34867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse von Gorgrond", description = "Kommandant, ich lasse meine Truppen hier, um den Pass zu bewachen, aber ich werde nicht tatenlos zusehen, wie der Feind den nächsten Angriff vorbereitet.\n\nIch will den Kampf ins Herz der Eisernen Horde nach Schwarzfels tragen, und das heißt, wir müssen dorthin gehen, wohin sich nur wenige Orcs wagen.\n\nGorgrond.\n\nEs ist ein wilder Ort, bevölkert von Riesen und allen möglichen anderen Monstern.\n\nWollt Ihr mit mir gemeinsam diese Wildnis durchqueren, um die Grundfesten der Eisernen Horde zu erschüttern?", sourceObjective = "Trefft Euch mit Durotan in Gorgrond.", completion = "Gorgrond ist kein Ort für eine Armee, Kommandant. Wir betreten nun die Stätte der Legenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[34868] = { id = 34868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung der Meister", description = "Die Zeit ist gekommen, die Meister der Brennenden Klinge herauszufordern.\n\nBegebt Euch ans Ende der Höhle. Dort werdet Ihr den Herausforderungsring finden, und mit ihm die Meister, die auf ihn hinabblicken.\n\nZieht das Schwert aus der Mitte des Rings, um Eure Herausforderung auszusprechen. Mein Klan schätzt Ehre über alles und wird Eurer Forderung nach einem Gerichtskampf nachkommen.\n\nAls Preis werdet Ihr mit dem Bauplan und Eurem Leben von dannen ziehen dürfen... oder Ihr werdet tot sein.", sourceObjective = "Überlebt den Gerichtskampf der Brennenden Klinge und beschafft die Garnisonsbaupläne.", progress = "Habt Ihr die Garnisonsbaupläne, Kommandant?", completion = "Die Garnisonsbaupläne. Hervorragend.\n\nJetzt gibt es nur noch eine Sache, um die wir uns kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34869] = { id = 34869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmeckt wie Hühnchen", description = "Habt Ihr einen Augenblick Zeit? Ich habe ein Problem von der Größe eines Elekks.\n\nJemand hat mir diese zwei hier, äh, verkauft, aber sie sind krank. Ich habe alles versucht, aber nichts hat geholfen.\n\nIch glaube, sie verhungern. Ich habe gehört, dass Elekks rohen Windroc mögen. Ganz schön widerlich, wenn Ihr mich fragt.\n\nAber wenn Ihr schon unterwegs seid, um das zu tun, was Ihr tut, könntet Ihr mir vielleicht etwas Vogelfleisch mitbringen?", sourceObjective = "Sammelt 10 Portionen rohen Windroc von Windrocs in Nagrand.", progress = "Windrocs? Ja, Nagrand ist voll von denen.\n\nSie scheinen hochgelegene Orte und Felsvorsprünge zu mögen.\n\nIch weiß doch auch nicht. Sehe ich aus wie ein Windrocflüsterer? Ihr seid der {class}.", completion = "Nach Hühnchen riechen tut es schon mal nicht!\n\nSchon gut, schon gut, gebt her. Ich werde sie füttern und dann sind alle zufrieden und ich kann einen schönen – äh, nun... dann geht es ihnen besser.\n\nJa.", sourceObjectiveStatus = "unverified-source-field" }
quests[34870] = { id = 34870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fürst der Gordunni", description = "Hexenfürst Morkurk ist der Anführer der Gordunni. Er ist derjenige, der den Handel mit der Eisernen Horde eingefädelt hat. Und was noch viel schlimmer ist: Mein ehemaliger Chef hat ihm einen meiner besten Streitkolben gegeben!\n\nWir müssen den Streitkolben zurückbekommen! Ich meine... wir müssen ihn töten, um das Jovit für Euer Arsenal sicherzustellen!\n\nMorkurk ist ein fähiger Magier, also seid auf der Hut. Hier, nehmt diesen Raketenrucksack und benutzt ihn, um Angriffen schnell ausweichen zu können oder... sowas in der Art.\n\nAch ja, wenn Ihr zufällig den Streitkolben irgendwo seht: Ich würde ihn gerne wiederhaben.", sourceObjective = "Besiegt Hexenfürst Morkurk in der Gordalfestung und erhaltet \"Zorn der Schmiede\".", progress = "Habt Ihr meinen Streitkolben?", completion = "Großartige Arbeit, Kommandant! Euren Fähigkeiten im Kampf kann wirklich niemand das Wasser reichen. Es ist mir eine Ehre, Euer Rüstungsschmied sein zu dürfen!\n\nGehen wir zum Außenposten zurück, damit wir uns einen Überblick über unsere neuen Vorräte verschaffen können. Ich habe noch ein paar Leuchtfeuer über, damit wir uns einen Rückflug rufen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[34871] = { id = 34871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche: Vorräte bergen" }
quests[34872] = { id = 34872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche: Belohnung für Wiederbeschaffung" }
quests[34873] = { id = 34873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche: Durchschlagen" }
quests[34874] = { id = 34874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nächste Schritte", description = "Ihr seid ja wirklich mit Feuer und Flamme bei der Sache!\n\nWir haben alles, was ich zur Herstellung der Schriftrolle benötige. Euer arkanes Sanktum wird in null Komma nichts nur so vor arkaner Energie strotzen.\n\nIch werde mich jetzt zurück nach Vol'jins Stolz teleportieren, um die Reagenzien zu kombinieren und Eure Streitkräfte aufzustellen. Kommt auch dort hin, sobald Ihr könnt.", sourceObjective = "Sprecht mit Magister Krelas in Vol'jins Stolz.", completion = "Eure Streitmacht brennt vor Leidenschaft für Eure Sache.\n\nEuch diesem erhabenen Feind entgegenzustellen, dürfte kein Leichtes gewesen sein. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[34875] = { id = 34875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nächste Schritte", description = "Wir haben es geschafft! Wir haben alle Reagenzien für die Schriftrolle beisammen. Euer arkanes Sanktum wird sehr bald Tagesgespräch in Draenor sein.\n\nIch werde jetzt zurück nach Fort Wrynn eilen, um sie fertigzustellen und Eure Männer zusammenzurufen. Wir treffen uns dort.", sourceObjective = "Sprecht mit Magistra Serena in Fort Wrynn.", completion = "Jetzt können wir uns um den künstlichen Nexus für Euren Turm kümmern!", sourceObjectiveStatus = "unverified-source-field" }
quests[34876] = { id = 34876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oma Loolas verlorene Liebe", description = "Oh, das war ja so furchtbar!\n\nMein Mann und ich waren zum Angeln im Sumpf. Ich bin irgendwann eingeschlafen. Und als ich wieder aufwachte, hatte er sich in eine Kröte verwandelt!\n\nIch bin mir sicher, dass einer dieser Schattenmondorcs dahinter steckt, von denen man so viel hört.\n\nUnd dann ist er in das schlammige Wasser gesprungen, bevor ich ihn mir schnappen konnte.\n\nWürdet Ihr mir helfen, meinen verlorenen Ehemann wiederzufinden, {class}?", sourceObjective = "Durchsucht lockeren Schlamm nach dem Ehemann der alten Loola.", completion = "Hm... Ich bin mir sicher, dass eine dieser Kröten mein Gatte ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[34877] = { id = 34877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschubunterbrechung", description = "Im Zuge meiner Untersuchungen habe ich ein permanentes arkanes Portal entdeckt, das von hier nach Hochfels führt.\n\nEs wird bewacht, aber es sollte nicht allzu schwer auszuschalten sein, sobald Ihr den Bereich gesichert habt.", sourceObjective = "Zerstört das Portal nach Hochfels.", completion = "Ausgezeichnet. Ich bezweifle, dass sie es wieder aufbauen werden, nachdem wir alle unsere Ziele hier erreicht haben.\n\nDieser Ort wird auch in Zukunft nur ein gescheiterter Außenposten des gorianischen Imperiums sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[34878] = { id = 34878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am Fuße der Festung", description = "Wir haben den Kampfgeist Eurer Streitkräfte geschürt und die Schriftrolle ist bereit.\n\nZeit, die zweite Phase einzuläuten: den Diebstahl eines Nexuskristalls aus einem schwer bewachten Stützpunkt der Oger.\n\nWir sparen uns die Schriftrolle auf, um Verstärkung anzufordern, wenn wir den Hexenfürsten der Gordunni stellen. Treffen wir uns am Fuße des Gordalvorgebirges, und nehmen wir uns das, was mehr oder weniger rechtmäßig Euch gehört!", sourceObjective = "Sprecht mit Magister Krelas am Eingang der Gordalfestung.", completion = "Entschuldigt, dass ich mich wegteleportiert habe. Ich weiß, das ist geschummelt.\n\nIch wollte Euch nur Feuer unterm Hintern machen, damit Ihr Euch schnellstens hierher bewegt!", sourceObjectiveStatus = "unverified-source-field" }
quests[34879] = { id = 34879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hereinschneien", description = "Hexenfürst Morkurk ist kein Dummkopf.\n\nEr hat überall im Vorgebirge, das vor ihrem Lager liegt, Katapulte in Stellung gebracht.\n\nAber sei's drum – ich weiß, wie wir mit ihnen fertigwerden können.\n\nSchaltet die Oger aus, die die Belagerungswaffen bewachen, und markiert dann die Standorte. In der Zwischenzeit bereite ich einen Wirbelzauber vor, mit dem wir dann das Problem von hier aus lösen können.\n\nWir treffen uns sofort danach beim Tor.", sourceObjective = "Helft Magister Krelas, 3 Felswerfer der Gordunni zu vernichten.", completion = "Bevor wir Morkurk herausfordern können, müssen wir noch etwas Anderes in der Festung erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34881] = { id = 34881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erde, Wind und Feuer... und Wasser", description = "Das Elementarplateau ist instabil geworden, und so wird es Zeit für den Zyklus der Wiedergeburt.\n\nEs ist ein natürlicher Bestandteil unseres Lebenszyklus, dass sich im Laufe der Zeit Unreinheiten in den Elementarkörpern ansammeln.\n\nEin Elementar, der zu starker Verunreinigung ausgesetzt ist, wird instabil und in manchen Fällen explosiv.\n\nEin wichtiger Bestandteil der Wiedergeburt ist reine Lebensessenz, wie sie auf dem Elementarplateau zu finden ist, sowie im Körper eines Elementargeists.\n\nKehrt mit der Essenz zu mir zurück, dann werde ich die Wiedergeburt einleiten.", sourceObjective = "Sammelt vier von jeder Lebensessenz auf dem Elementarplateau.", progress = "Bringt mir die Lebensessenzen der Elemente, auf dass ich die Samen der Wiedergeburt einpflanzen kann.", completion = "Das habt Ihr gut gemacht.\n\nObwohl das Elementarplateau nicht länger stabil ist, wird doch schon bald der Zyklus der Wiedergeburt erneut stattfinden und die Elemente werden wiedergeboren.", sourceObjectiveStatus = "unverified-source-field" }
quests[34882] = { id = 34882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klingen im Dunklen", description = "Diese Orcs haben also Ishaals Kugel in die Finger bekommen? Das würde den gefährlich aussehenden Kerl erklären, der kurz vor Euch in dieses Reich hinübertrat.\n\nNicht jeder bewältigt den Übergang so... würdevoll wie Ihr. Dieser Narr kämpft immer noch gegen seinen eigenen Geist, stolpert herum und murmelt Unsinn.\n\nBald wird er wieder von der Kugel angezogen werden, die ihn wahrscheinlich ins Terokkversteck führen würde.\n\nEs wäre besser, ihn jetzt auszuschalten, solange er noch verwirrt ist.", sourceObjective = "Tötet Malrok Dornnarbe im Akrazversteck.", completion = "Das war ein großer Kerl, oder? Die Scheusale dürften sich über ein Festmahl freuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34883] = { id = 34883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Festmahl der Schatten", description = "Viele Arakkoa starben im Akrazversteck. Von außen betrachtet sieht alles ganz still aus. Verlassen.\n\nAber an diesem Ort zwischen den Welten ist der Tod allgegenwärtig.\n\nFreigesetzte Lebensessenzen dringen von der anderen Seite ein und sind ein Festmahl für die Wesen, die hier umherstreifen.\n\nTötet die Schattenkreaturen hier und sammelt den feinen Staub auf, den ihre Kadaver freisetzen. Ich werde viel davon benötigen, um die Riten des Klauenkönigs durchführen zu können.", sourceObjective = "Sammelt 10 Portionen Schattenstaub.", progress = "Ihr kennt doch diese Elixiere, die Ihr so begeistert hinuntergestürzt habt?\n\nDie bestehen aus diesem Zeug.", completion = "Gut. Mit so viel Staub können wir tief genug eintauchen, um die Zuflucht des Klauenkönigs zu erreichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34884] = { id = 34884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kaliriflüsterer", description = "Ein wichtiger Verbindungsmann lebt auf der Schattenlichtung ganz in der Nähe. Er ist sanftmütig, aber er trainiert riesige Kaliri, was ziemlich gefährlich ist.\n\nEinmal hat er behauptet, sie könnten einen Rylak vom Himmel holen, aber das glaube ich erst, wenn ich es sehe.\n\nSkizzik bewahrt einen wertvollen Schatz für mich auf. Findet Skizzik und bringt ihn ins Terokkversteck, wenn Ihr könnt. Ihr solltet aber wenigstens den Hammer zurückholen, den ich ihm anvertraut habe.", sourceObjective = "Besorgt den abgenutzten Hammer von Skizzik.", progress = "Gibt es Neuigkeiten aus Skizzik?", completion = "Ich verstehe. Na ja, immerhin ist der Hammer in Sicherheit.\n\nWie Ihr vielleicht bereits vermutet, handelt es sich um ein weiteres Relikt des Klauenkönigs.", sourceObjectiveStatus = "unverified-source-field" }
quests[34885] = { id = 34885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mutter aller Dornen", description = "<Unter Skizziks ausgestreckter Hand sind in den Staub gekritzelte Buchstaben zu sehen:\n\nd o r n m u t t e r\n\nVerheerer, die von der Zerschmetterten Hand hergebracht wurden, haben das Aviarium übernommen und vermehren sich schnell. Wenn man sie sich selbst überlässt, könnte es innerhalb weniger Tage in der ganzen Gegend – auch im Terokkversteck – nur so von ihnen wimmeln.>", sourceObjective = "Tötet 5 Schattenrückenverheerer und die Schattenrückenmutter.", completion = "Es ist schade um Skizziks Aviarium. Percy kam von dort. Skizzik hatte kein Interesse mehr an den \"Winzlingen\", nachdem er angefangen hatte, hauptsächlich die großen Exemplare zu züchten.\n\nWenn ich ehrlich bin, konnte ich die Riesenviecher aber noch nie leiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[34886] = { id = 34886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vogelbaby", description = "<Ikky piepst noch einmal und beginnt dann, an seiner Klaue zu nagen.\n\nAuf dem Hügel in der Nähe seht Ihr, wie sich winzige Verheererlarven durch das Gras winden.>", sourceObjective = "Sammelt 8 Verheererlarven auf der Schattenlichtung.", progress = "<Ikky schaut Euch mit der Klaue in seinen Schnabel an und lässt ein gedämpftes Piepsen vernehmen.>", completion = "<Ihr haltet die Larvenwürmer in der Hand, sprecht Euch selbst Mut zu und bereitet Euch darauf vor, sie nach der Art einer guten Vogelmutter vorzukauen.\n\nGlücklicherweise schnappt sich aber Ikky die Würmer, bevor Ihr das Vorhaben in die Tat umsetzen könnt.\n\nDie Kaliri scheinen solche Fürsorge nicht zu kennen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[34887] = { id = 34887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo wir schon mal hier sind", description = "Ah, der Hochmut dieser Oger!\n\nEr wird ihnen immer wieder zum Verhängnis.\n\nMorkurk hat seine Schergen mit Hilfe von verzauberten Armreifen mit arkaner Stärke erfüllt.\n\nWir können diese Armreife in Reagenzien auflösen, die zweifelsohne für unser arkanes Sanktum von Nutzen sein werden. Wie wäre es, wenn Ihr welche besorgt, wo wir schon einmal hier sind?", sourceObjective = "Sammelt 8 Runenperlen der Gordunni ein.", progress = "Die meisten Magier vernachlässigen heutzutage den Nutzen von arkanem Staub, doch sie irren sich.", completion = "Ja, damit kann man ganz sicher etwas anfangen! Vertraut mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[34888] = { id = 34888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wehrhafte Wesire", description = "Wir sind zwar hinter Hexenfürst Morkurk her, aber wir sollten ihn nicht direkt angreifen.\n\nSeine drei Leutnants – Vorgorsh, Zulmork und Cromaug – sind die einzigen anderen fähigen Zauberer der Gordunni, die noch übrig sind. Sie sind Morkurk treu ergeben.\n\nIch vermute, dass sie dem Hexenfürsten zu Hilfe eilen würden, wenn wir ihn angreifen. Schalten wir sie zuerst aus.", sourceObjective = "Tötet Wesir Vorgorsh, Wesir Zulmork und Wesir Cromaug.", completion = "Jetzt, wo sie aus dem Weg sind, können wir uns Morkurk vornehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34889] = { id = 34889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kugeln der Macht", description = "Bei meinem Plan gibt es einen kleinen Haken, um den wir uns zunächst kümmern müssen.\n\nMorkurk hat mächtige Schutzzauber in der Gordalfestung aufgestellt, um jede Art von Massenbeschwörung zu verhindern. Und das ist natürlich abträglich für unsere Pläne mit der Schriftrolle der Massenteleportation.\n\nGlücklicherweise würde aber kein Oger je damit rechnen, dass ein oder zwei einzelne Feinde es wagen könnten, in ihre Festung einzubrechen.", sourceObjective = "Zerstört 5 Astralzauber.", completion = "Morkurk kann uns jetzt nicht mehr aufhalten.\n\nWirklich gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[34890] = { id = 34890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Schritt", description = "Es ist an der Zeit, Feuer mit Feuer zu bekämpfen.\n\nWir haben Morkurk in die Enge getrieben. Er ist schutzlos. Benutzt die Schriftrolle, sobald Ihr Morkurk in ein Gefecht verwickelt habt...\n\n...und genießt dann das Feuerwerk.", sourceObjective = "Besiegt Hexenfürst Morkurk und bergt den Arkanen Nexus in der Gordalfestung.", progress = "Oger. Immer sind die Oger schuld.", completion = "So habe ich mir das vorgestellt.\n\nJetzt nichts wie weg hier!", sourceObjectiveStatus = "unverified-source-field" }
quests[34891] = { id = 34891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abstimmung auf die Elemente", description = "Viele Schamanen haben den Segen des Throns der Elemente ersucht.\n\nIndem sie einen elementaren Bund mit den Zornen schließen, erfahren sie nicht bloß den Willen der Elemente in Draenor, sondern können auch die enormen elementaren Kraftquellen anzapfen.\n\nWenn Ihr die wahre Ursache für Gordawgs Verschwinden herausfinden wollt, muss Euch gelingen, wobei andere gescheitert sind – das Ritual der Bindung.\n\nZunächst müsst Ihr Euch darauf vorbereiten. Sucht die Elementarsäulen auf dem Plateau auf und bringt Euren Geist mit den Elementen in Einklang.", sourceObjective = "Begebt Euch zu den vier Elementarsäulen.", completion = "Gut gemacht, {name}.\n\nIhr habt Euch mit den vier Elementarsäulen verbunden, und damit auch Eure Lebensenergie mit allen Elementen Draenors.\n\nNun seid Ihr bereit für das Ritual der Bindung.\n\nSprecht mich an, wenn Eure Arbeit auf dem Elementarplateau beendet ist. Dann können wir sofort beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34893] = { id = 34893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wächter des Plateaus", description = "Das Elementarplateau ist die Zufluchtsstätte der Elementargeister von Nagrand.\n\nDie größten von ihnen sind die Wächter, mächtige Elementargeister, die über ihre Domäne wachen.\n\nDie Wächter sind eigentlich reine und mächtige Geister, doch durch die Störung des natürlichen Gleichgewichtes wurden auch sie instabil und nun korrumpieren sie die niederen Elementare um sie herum.\n\nUm das Gleichgewicht auf dem Plateau wiederherzustellen, müssen die Wächter vernichtet werden. Erst dann kann der Zyklus der Wiedergeburt einsetzen.", sourceObjective = "Vernichtet die korrumpierten Wächter auf dem Elementarplateau.", completion = "Jeder der Wächter, die Ihr zur Ruhe gebettet habt, war einst ein mächtiger und edler Elementargeist.\n\nWenn die Zeit reif ist, werden sie durch den Zyklus der Wiedergeburt wiederauferstehen, doch muss Gordawg gefunden und das Gleichgewicht wiederhergestellt werden, sonst wird das Plateau erneut instabil werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[34894] = { id = 34894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine seltene Blume", description = "Vor vielen Jahren hatte ich eine Lebensgefährtin, Dahaka. Wir haben nur eine kurze Zeit zusammen verbringen können, bevor sie mir genommen wurde.\n\nIch kann auf ein langes Leben zurückblicken, aber niemals zuvor und danach habe ich einen größeren Schmerz verspürt als an jenem Tag. Ich war jung und voller Trauer und die Erde erzitterte unter meinem Zorn. Ich habe sie genau hier auf dieser Klippe begraben.\n\nIch möchte auch hier begraben werden, aber zuvor muss ich Euch um einen Gefallen bitten.\n\nIn einer Höhle, in der feurigen geschmolzenen Erde des Plateaus, wächst eine seltene Blume. Sie war ihre Lieblingsblume.\n\nIch möchte diese Blume noch einmal auf ihr Grab legen, bevor ich selbst sterbe.", sourceObjective = "Pflückt die Glutblüte vom Elementarplateau.", progress = "Habt Ihr die Glutblüte?", completion = "Ihr habt mir eine sehr schöne Glutblüte mitgebracht. Ich weiß um die Gefahren, die Ihr dafür ausstehen musstet, und danke Euch ganz herzlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[34895] = { id = 34895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche: Bomben abwerfen" }
quests[34896] = { id = 34896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsquest: Getarnte Rangari" }
quests[34897] = { id = 34897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rangari gesucht", description = "Ihr habt ein gutes Auge, {class}.\n\nIn der Nachtmarsch verbergen sich noch mehr Rangari wie ich.\n\nIch brauche Berichte von ihnen, um sicherzustellen, dass die Gegend sicher ist.\n\nKönntet Ihr mir dabei helfen?", sourceObjective = "Findet die 5 verborgenen Rangari.", completion = "Danke für den Bericht, {name}. Wir müssen die Südliche Wildnis genau im Auge behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[34898] = { id = 34898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ikky", sourceObjective = "<Ikky zwitschert Euch aufgeregt an.\n\nSieht aus, als hättet Ihr einen neuen Freund gefunden.>", sourceObjectiveStatus = "unverified-source-field" }
quests[34899] = { id = 34899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Qual der Wahl", description = "Wir sind bereit, mit dem Bau zu beginnen. Ihr müsst jetzt nur noch eine Entscheidung treffen.\n\nDie Baupläne liegen auf dem Zeichentisch. Schaut sie Euch an.\n\nLasst mich dann wissen, ob wir einen Pferch oder ein Panzerwerk bauen sollen.", sourceObjective = "Benutzt den Zeichentisch, um Euch zwischen dem Bau eines Pferchs und eines Panzerwerks zu entscheiden.", completion = "Dies ist ein großer Moment, Kommandant. Thaelin und seine Peons werden sofort mit der Arbeit beginnen.\n\nIhr werdet sehen, dass Eure Entscheidung uns dabei helfen wird, den Kriegshymnenklan zu besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34900] = { id = 34900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Babys", description = "Schon besser, aber irgendetwas stimmt noch immer nicht. Ich verzweifle hier langsam, {name}.\n\nDarf ich Euch {name} nennen? Fantastisch.\n\nHört mal, ich glaube, ich hab's jetzt raus. Ich weiß, was nicht in Ordnung ist.\n\nSie vermissen ihre Babys.\n\nJa! Als sie das erste Mal hierher kamen, sagten diese, äh... Bastards von Jägern, die sie... im Stich ließen, dass sie die Jungen zurückgelassen hatten.\n\nWenn wir sie vor einem Leben in Elend bewahren, diese Babys retten <gemurmelt> und einen ordentlichen Profit dabei machen wollen, müssen wir ihnen ein paar neue Junge besorgen!", sourceObjective = "Lockt 5 zarthufige Wiesentrampler an.", completion = "Ihr habt es vollbracht, {name}! Mama, Papa und die ganze Familie. Mir kommen die Tränen.\n\nHier, nehmt dieses Mickrige hier. Nun, da ich die ganze Herde habe, ist es nur ein weiteres Maul, das gefüttert werden will, und auf dem Markt wird es auch nicht viel einbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34904] = { id = 34904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portalvision" }
quests[34905] = { id = 34905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Platzhalter-Quest" }
quests[34906] = { id = 34906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krelas beschworen" }
quests[34907] = { id = 34907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette/Schatz: Lagunenteich/Riesenmuschel" }
quests[34908] = { id = 34908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am Fuße der Festung", description = "Eure Streitkräfte scharren mit den Füßen und die Schriftrolle ist bereit.\n\nZeit, die zweite Phase einzuläuten: den Diebstahl eines Nexuskristalls aus einem schwer bewachten Ogerstützpunkt.\n\nWir sparen uns die Schriftrolle auf, um Verstärkung anzufordern, wenn wir den Hexenfürsten der Gordunni stellen. Stoßt am Fuße des Gordalvorgebirges zu mir, dann nehmen wir die Festung selbst in Angriff!", sourceObjective = "Sprecht mit Magistra Serena am Eingang der Gordalfestung.", completion = "Wir haben keine Zeit zu verlieren. Die Gordalfestung erwartet uns dort auf dem Hügel.", sourceObjectiveStatus = "unverified-source-field" }
quests[34909] = { id = 34909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo wir schon mal hier sind", description = "Die imperialen Oger gelten als kalt und berechnend.\n\nUnser Glück, dass ihre Berechnungen selten stimmen.\n\nMorkurks Schergen tragen verzauberte Armreife, die mit arkaner Stärke erfüllt sind.\n\nUnd da wir sie ohnehin ins Jenseits befördern müssen, können wir genauso gut ein paar Reagenzien aus ihren Armreifen gewinnen.", sourceObjective = "Sammelt 8 Runenperlen der Gordunni ein.", progress = "Ah, arkanes Pulver. Das erinnert mich an meine Zeit als Lehrling.", completion = "Die besten sind sie nicht, aber ich denke, sie werden für uns ihren Wert haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[34910] = { id = 34910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wehrhafte Wesire", description = "Wir können nicht einfach hineinplatzen, Hexenfürst Morkurk töten und wieder gehen.\n\nSeine drei Leutnants – Vorgorsh, Zulmork und Cromaug – sind ihm treu ergeben und selbst fähige Zauberer.\n\nIch vermute, dass sie dem Hexenfürsten zu Hilfe eilen würden und uns überlegen wären, wenn wir ihn sofort angreifen. Wir müssen die Leutnants zuerst ausschalten.", sourceObjective = "Tötet Wesir Vorgorsh, Wesir Zulmork und Wesir Cromaug.", completion = "Jetzt, wo sie aus dem Weg sind, können wir uns Morkurk vornehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34911] = { id = 34911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kugeln der Macht", description = "Leider gibt es ein kleines Problem.\n\nHexenfürst Morkurk hat mächtige Schutzzauber in der Gordalfestung aufgestellt, um jede Art von Massenbeschwörung zu verhindern – was für unseren Plan etwas abträglich ist.\n\nGlücklicherweise würde aber kein Oger jemals glauben, dass ein oder zwei einzelne Feinde es wagen könnten, sie anzugreifen. Wir sollten uns also relativ leicht in die Festung schleichen können.", sourceObjective = "Zerstört 5 Astralzauber.", completion = "Die Zerstörung dieser Schutzzauber war der Schlüssel zum Erfolg. Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[34912] = { id = 34912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Schritt", description = "Wir haben Morkurk in die Enge getrieben. Er gehört uns. Benutzt die Schriftrolle, sobald Ihr Morkurk in ein Gefecht verwickelt habt...\n\n...und genießt dann wie Eure Streitkräfte ihm den Garaus machen.", sourceObjective = "Besiegt Hexenfürst Morkurk und bergt den Arkanen Nexus in der Gordalfestung.", progress = "Alles kommt auf diesen Moment an.", completion = "Sieht so aus, als wäre Morkuk uns beiden nicht gewachsen gewesen, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[34913] = { id = 34913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hereinschneien", description = "Hexenfürst Morkurk, der Anführer der Festung, hat überall entlang der Straße, die in ihr Lager führt, Katapulte in Stellung gebracht.\n\nAber das dürfte kaum ein Problem für uns darstellen.\n\nSchaltet die Oger an den Katapulten aus und markiert ihre Standorte. Der Wirbelzauber, den ich vorbereitet habe, wird den Rest erledigen.\n\nStoßt am Festungstor zu mir, wenn die Katapulte aus dem Weg geräumt sind.", sourceObjective = "Helft Magistra Serena, 3 Felswerfer der Gordunni zu vernichten.", completion = "Die Schriftrolle der Massenteleportation wäre bereit, doch wir können sie noch nicht einsetzen. Zunächst gilt es, die nötigen Vorkehrungen zu treffen, um unseren Erfolg sicherzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34914] = { id = 34914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gelegenheitsziel: Telaar", description = "Wir haben Berichte erhalten, dass eine Draeneienklave in Telaar vom Kriegshymnenklan überrannt wurde.\n\nIch habe eine kleine Gruppe Schattenjäger entsandt, um die Lage zu überprüfen.\n\nDie Anführerin ist Kajassa. Könntet Ihr sie dort treffen?", sourceObjective = "Sprecht mit Schattenjägerin Kajassa in Telaar.", completion = "Bin froh, dass Aggra Euch geschickt hat, Kommandant. Die Lage is' düster. Un' sie wird nich' besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[34915] = { id = 34915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich helf töt'n", description = "Der Kriegshymnenklan hat alle Draeneispäher umgebracht. Aber wir werd'n ihnen diesen Ort nich' überlassen.\n\nIhr und ich, Kommandant. Wir werden sie alle umbring'n.\n\nIhr lenkt sie ab und ich erledige sie mit meinem Loa. Ihr werdet schon seh'n.", sourceObjective = "Tötet 12 Kriegshymnenkrieger in Telaar.", completion = "Oh, das war 'n großer Spaß. Ihr und ich, wir arbeit'n gut zusammen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[34916] = { id = 34916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samedis Segen", description = "Drei meiner Schattenjäger hatt'n mich begleitet. Der Kriegshymnenklan hat sie umgebracht.\n\nWir müssen dafür sorg'n, dass ihre Seelen sich auf die letzte Reise mach'n können. Wenn Ihr sie zuerst findet, wendet dies hier auf ihre Leichname an.\n\nDamit schickt Ihr ihre Seelen zu Samedi, dem Loa des Grabes.", sourceObjective = "Wendet Samedis Fetisch auf die Leichen der Schattenjäger an.", completion = "Sie sin' jetzt an einem besseren Ort. Samedi wird sie jetzt alle auf ihre Missionen entsend'n.\n\nIch dank Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[34917] = { id = 34917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schilde hoch!", description = "Die Rudelführerin des Kriegshymnenklans versucht, den Schild von Telaar hochzufahren. Wenn Kargor dies gelingt, verfügt der Kriegshymnenklan über eine uneinnehmbare Basis.\n\nBis jetzt hat sie den Schild nur initialisiert. Leider sind dadurch die Rudelführerin und ihr Schamane beim Hauptkristall geschützt.\n\nAktiviert die Kristalle rund um Telaar herum. Dadurch wird der Schild auf seine vollständige Größe ausgeweitet.\n\nUnd wenn Euch das gelingt, wird Kargor angreifbar sein.", sourceObjective = "Aktiviert die vier Telaarkristalle.", completion = "Bald wird der Schild ganz Telaar abdecken. Und dann sind wir alle dort drinnen gefangen.\n\nUnd dann werden wir die Rudelführerin töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[34918] = { id = 34918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schilde unten!", description = "Die Zeit ist gekommen, Kommandant. Rudelführerin Kargor und der Arkonitschild sind nich' mehr geschützt.\n\nWir müss'n sie töten und den Schildkristall zerstör'n.", sourceObjective = "Tötet Rudelführerin Kargor und zerstört den Arkonitschild.", completion = "Es tut mir leid um Kajassas Schattenjägerinnen, aber wir konnten Telaar nicht dem Kriegshymnenklan überlassen.\n\nMit dem Tod von Kargor und ihrem Rudel sind wir der Invasion von Grommashar, der Heimat des Kriegshymnenklans, einen Schritt näher gekommen.\n\nUnd damit einen Schritt näher der Gerechtigkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[34920] = { id = 34920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zauberschutz zerstören" }
quests[34921] = { id = 34921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kult der Rabensprecher", description = "Diese Ausgestoßenen sind nicht die einzigen verfluchten Arakkoa, die in Arak die Stellung halten.\n\nEin merkwürdiger Kult ist entstanden, der Ka'alu, meine Gefährtin und Hüterin meiner Brut verehrt. Die Anhänger dieses Kults gelten als ziemlich... eigenartig.\n\nNichtsdestotrotz werden die Ausgestoßenen ihre Hilfe brauchen. Ohne die Flügel der Raben wird Iskars Kampf gegen die Spitzen kaum Aussicht auf Erfolg haben.\n\nNehmt diese Feder und legt sie in den Gabenkorb südlich von hier. Die so genannten \"Rabensprecher\" werden bestimmt davon Notiz nehmen.", sourceObjective = "Legt die Feder von Anzu in den Gabenkorb am Knarzwaldpass.", completion = "Ah, Ihr seid gekommen, um die Wahrheit zu erfahren.\n\nZuerst werden wir Eure Hingabe auf die Probe stellen müssen, ja!", sourceObjectiveStatus = "unverified-source-field" }
quests[34922] = { id = 34922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worte der Rabenmutter", description = "Wir kamen hierher, um mit dem Anrufungsritual die Rabenmutter zurückzubringen. Wir hatten Teile der alten Schriftrolle an alle verteilt und gerade mit dem Ritual begonnen, als wir von den Blutmähnen angegriffen wurden. Der Großteil des Schwarms wurde dabei getötet, und die Fragmente der Schriftrolle wurden über unsere ganze Heimat verstreut.\n\nDas Ritual ist gescheitert, aber wir werden nicht zulassen, dass diese Bastarde unseren Glauben brechen. Wir müssen unsere Gebete hier fortsetzen und wären Euch sehr dankbar, wenn Ihr die Fragmente der Schriftrolle für uns wiederbeschaffen könntet.", sourceObjective = "Bergt 8 Schriftrollenfragmente der Rabensprecher.", progress = "Wir brauchen alle heiligen Schriften! Wir können es uns nicht leisten, auch nur eine davon zu verlieren!", completion = "Ah! Die Abschriften des Rituals!\n\nGelobt sei die Rabenmutter!\n\nÜberreicht sie mir, aber immer eine nach der anderen. Wir dürfen nicht die Macht des Lichts beschwören.", sourceObjectiveStatus = "unverified-source-field" }
quests[34923] = { id = 34923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Blutmähnen", description = "Kaum waren wir angekommen und hatten mit der Zeremonie des kopflosen Federviehs begonnen, fielen die Blutmähnen wie aus dem Nichts über uns her.\n\nSicher möchte die Rabenmutter dadurch überprüfen, ob ihre Kinder ihrer Aufmerksamkeit würdig sind. Doch keine Sorge, wir halten stand und setzen unsere Gebete fort. Komme, was wolle!\n\n<Sekara beugt sich näher zu Euch und flüstert.>\n\nWenn Ihr allerdings die Blutmähnen und ihren Anführer ausschalten könntet, wäre auch das ein Segen.", sourceObjective = "Tötet Jagdmeister Leidzahn und 10 Klingenklauen der Blutmähnen.", completion = "Eure Stärke hat uns etwas Zeit verschafft, um zu rasten und unsere Rituale fortzusetzen.\n\nMöge Euch die Rabenmutter stets unter ihre Fittiche nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34924] = { id = 34924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eierdiebe", description = "Die Blutklauen sind sadistische Kreaturen. Sie haben die Rabenskar schon früher angegriffen und die Eier der heiligen Raben gestohlen.\n\nWenn Ihr im Gebiet der Blutklauen unterwegs seid, haltet die Augen nach den Eiern offen.\n\nIch werde beim Nest mit so vielen Körben wie möglich auf Euch warten.", sourceObjective = "Sammelt 8 Schreckensrabeneier.", progress = "Habt Ihr die gestohlenen Rabeneier gefunden?", completion = "Diesen armen Raben ist ein schreckliches Schicksal im Land der Blutklauen erspart geblieben.\n\nWir werden uns viel besser um sie kümmern.\n\nDanke!", sourceObjectiveStatus = "unverified-source-field" }
quests[34925] = { id = 34925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Politur des Eisenthrons", description = "Diese stinkenden Schwarzfelsfeiglinge glauben, sie könnten mich demütigen.\n\nSie machen mich nur noch wütender.\n\nAufseher Gotrigg ist in der Hütte da drüben und hat den Schlüssel für meine Fesseln. Wenn ich hier raus will, brauche ich den Schlüssel. Danach... wird meine Rache ihren Lauf nehmen.", sourceObjective = "Nehmt Aufseher Gotrigg in dem Gebäude in der Nähe den Schlüssel für Ga'nars Fesseln ab.", progress = "Ihr werdet ihm den Schlüssel aus seiner kalten, hässlichen Hand reißen müssen.", completion = "<Ga'nar befreit seinen Hals aus der Fessel.>\n\nViel besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[34929] = { id = 34929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Gennadian" }
quests[34931] = { id = 34931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Lagerversteck der Frostwölfe 04" }
quests[34932] = { id = 34932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarnung des Betrügers", description = "In einer Höhle nicht weit von hier lebt eine alte Frau namens Challe.\n\nWir kennen uns schon seit vielen Jahren, seit ich ein junger Mann war. Doch während ich alt und grau wurde, hat sie ihre Jugend und Schönheit bewahrt.\n\nChalle war wegen meiner Liebe zu Dahaka eifersüchtig, und ich hege schon lange den Verdacht, dass Challe eine Rolle bei ihrem Tod gespielt hat. Ohne Beweise jedoch kann ich sie nicht zur Rechenschaft ziehen.\n\nBitte trefft Euch mit Challe und erzählt ihr, dass ich im Sterben liege. Sagt ihr, dass ich die Wahrheit über Dahakas Tod erfahren möchte, bevor ich diese Welt verlasse.", sourceObjective = "Sprecht mit Challe, um die Wahrheit zu erfahren.", completion = "Challe, diese bösartige Hexe!\n\nHätte ich doch nur viel früher einen Beweis für ihren Verrat gehabt, dann hätte ich ihr das verdorbene Herz aus der Brust gerissen und unter meinen Füßen zertreten!\n\nIhr habt mir wie gewünscht die Wahrheit verraten, und dafür gebührt Euch mein Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[34934] = { id = 34934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erste Verteidiger" }
quests[34935] = { id = 34935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begrüßung hinter der Mauer" }
quests[34936] = { id = 34936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Madame Senas Sondervorrat" }
quests[34937] = { id = 34937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Skaggits Sondervorrat" }
quests[34938] = { id = 34938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ralshiaras Untergang", description = "In den Schriften der aufgehenden Sonne steht geschrieben, dass bei einem Frühstück immer einige Eier beschädigt werden.\n\nDie Matrone der Blutmähnen, Ralshiara, labt sich an heiligen Rabeneiern. Wie kann sie es wagen! Für ihre Sünden muss sie mit dem Leben bezahlen!\n\nFolgt dem Weg südwärts über die Berge in die verfluchte Heimat der Blutmähnen.\n\nNehmt dieses Schmuckstück an Euch. Es ist uns aus den Himmeln zugefallen, ein Zeichen der Gunst der Rabenmutter. Mit ihm könnte es Euch gelingen.", sourceObjective = "Tötet Ralshiara.", completion = "Jeder soll erfahren, dass am heutigen Tage der Fremde siegreich im Kampf gegen die gefürchtete Erzfeindin unseres Schwarms zurückgekehrt ist!\n\nGelobt sei die Rabenmutter!", sourceObjectiveStatus = "unverified-source-field" }
quests[34939] = { id = 34939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Blutmähnen die Krallen kürzen", description = "Die Schriftrolle der Predigten lehrt uns: \"Beißt die Klaue, die Euch schlägt!\"\n\nNehmt den Pfad südlich von hier, der über den Berg ins Blutmähnental im Westen führt. Dort findet Ihr jene ihres Stammes, die eine primitive Form der Magie einsetzen können. Tötet sie und schneidet ihnen ihre Pfoten ab.\n\nSobald Ihr ein paar davon habt, bringt sie zu mir ins Nest, auf dass ich sie der Rabenmutter darbieten kann!", sourceObjective = "Erbeutet 6 Pfoten von Schamanen der Blutklauen.", progress = "In der Schriftrolle der Predigten steht geschrieben, dass die Rabenmutter nicht geduldig ist, ebenso wenig wie ich.\n\nHabt Ihr die Blutmähnenpfoten dabei?", completion = "Das wird ein hervorragendes Opfer für die Rabenmutter! Möge sie sich an unseren Feinden gütlich tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[34940] = { id = 34940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Spinnendegen" }
quests[34941] = { id = 34941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geteilte Schuld", description = "Die sterblichen Hüllen, die wir Körper nennen, sind nicht unser Eigen. Der Körper ist ein Geschenk der Erde, das eines Tages zurückgegeben werden muss.\n\nFür diesen Körper ist die Zeit gekommen, zu den Elementen zurückzukehren.\n\nWisset, dass Ihr eine schwere Bürde von einem alten Herzen genommen habt, {name}. So kann ich diese Welt ohne Reue verlassen. Ich kämpfte für mein Land und mein Volk, ich diente den Elementen und ich liebte.\n\nEs wäre mir eine Ehre, wenn Ihr bei meinen letzten Atemzügen Beistand leistet, {class}.", sourceObjective = "Sprecht mit Gar'rok.", completion = "Gar'rok war ein treuer Hüter und ein wahrer Freund. Er wird mir fehlen, doch das ist der Lauf des Lebens in dieser Welt.\n\nBeizeiten werden wir einen neuen Hüter der Elemente bestimmen, und er wird uns dienen, wie Gar'rok es vor ihm getan hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[34942] = { id = 34942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück aus dem Jenseits", description = "Wir müssen mit den Vorbereitungen für die Rückkehr des Klauenkönigs beginnen.\n\nAus diesem Reich kann ich mich schnell ins Terokkversteck begeben.\n\nIhr solltet allerdings zur anderen Seite zurückkehren, denn Ihr seid mächtig und würdet nur ungebetene Aufmerksamkeit erregen.", sourceObjective = "Sprecht mit dem Schattenweisen Iskar im Terokkversteck.", completion = "Ausgezeichnete Arbeit. Ishaal und Zellek haben bereits mit den Riten begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34943] = { id = 34943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein alter Freund", description = "Seit Anbeginn der Zeit wurde immer ein Schamane zum Hüter des Throns der Elemente berufen. Dies ist eine lebenslange Aufgabe und neue Hüter werden nur berufen, wenn der vorherige Hüter gestorben ist.\n\nGar'rok diente uns jahrelang als treuer Hüter, der das Elementarplateau durch zahllose Zyklen der Wiedergeburt hindurch bewacht hat.\n\nUnser Hüter liegt im Sterben, und schon bald wird ein neuer Hüter berufen werden. Er sollte nicht allein sein, wenn er stirbt. Bitte sucht ihn auf, {name}.\n\nLindert seine Schmerzen.", sourceObjective = "Sprecht mit Gar'rok.", completion = "Kalandrios hat Euch zu mir geschickt? Ich fühle mich geehrt.\n\nDie Zorne sind wahrhaft weise. Sie wissen, was mein Herz bedrückt.\n\nIhr wisst es vielleicht nicht, aber sie haben Euch geschickt, um einem sterbenden Schamanen einen letzten Wunsch zu erfüllen.\n\nUnd dafür bin ich sehr dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[34945] = { id = 34945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suchmarkierung: Unterseher Blutmähne Vignette" }
quests[34946] = { id = 34946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffen mit Morkurk" }
quests[34947] = { id = 34947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schredderhandbuch", description = "Hey! Ich habe gehört, dass sich ein seltsamer Gegenstand in der Nähe befindet. Die Späher sagen, es würde sich um eine Art Schredderhandbuch handeln.\n\nKönntet Ihr mal für mich nachschauen? Ich frage mich, ob das etwas mit diesem neuen Prototypen zu tun hat, von dem ich so viel gehört habe...", sourceObjective = "Findet den Stilllegungsbefehl für den Eisenschredder.", completion = "Diese Befehle scheinen direkt von Orgrim Schicksalshammer zu kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34948] = { id = 34948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schredderhandbuch", description = "Ich habe gehört, dass die Ingenieure der Eisernen Horde einen neuen Schredderprototypen entwickelt haben.\n\nIch finde, wir sollten mal einen Blick auf diese Entwicklung werfen. Einer der Schattenjäger hat eine Art Handbuch für diesen Schredder entdeckt. Es könnte mit diesem Prototypen in Zusammenhang stehen.", sourceObjective = "Findet den Stilllegungsbefehl für den Eisenschredder.", completion = "Diese Befehle scheinen direkt von Orgrim Schicksalshammer zu kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34949] = { id = 34949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufnahme in die eigenen Reihen", sourceObjective = "Es war ganz schön kniffelig, bis wir Euren Turm hell zum strahlen gebracht hatten. Wenn es Euch recht ist, möchte ich mich gerne Eurem Feldzug anschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34950] = { id = 34950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreckenskolben", description = "Ganz in der Nähe hat eine Einheit der Eisernen Horde eine strategische Schlüsselposition mit bemerkenswerter Leichtigkeit eingenommen.\n\nWährend der Belagerung benutzten sie eine Maschine namens Schreckenskolben mit verheerenden Folgen. Ich glaube, wir täten gut daran, diese Maschine zu zerstören, bevor wir uns in Tuurem in den Kampf gegen die Eiserne Horde stürzen.", sourceObjective = "Vernichtet Schreckenskolben.", completion = "Eine Höllenmaschine.", sourceObjectiveStatus = "unverified-source-field" }
quests[34951] = { id = 34951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Man nennt ihn Lantresor von der Klinge", description = "Der Klan der Brennenden Klinge in Hallvalor beliefert den Kriegshymnenklan mit Waffen und Kriegern. Wir müssen etwas dagegen unternehmen.\n\nEs gibt da einen Klingenmeister, der schon vor Jahren vom Klan der Brennenden Klinge verbannt wurde. Sie nennen ihn \"Lantresor von der Klinge\".\n\nMeine Rangari haben mir berichtet, dass er kürzlich nach Hallvalor zurückgekehrt ist, um die Klingenmeisterführung herauszufordern. Allerdings haben sie ihn stattdessen in Ketten gelegt.\n\nVielleicht ist er noch am Leben. Vielleicht kann er Euch im Kampf gegen den Klan der Brennenden Klinge helfen.", sourceObjective = "Findet Lantresor von der Klinge in Hallvalor.", completion = "Wer seid Ihr?\n\nErkennt Ihr den Tod nicht, wenn Ihr Ihn seht, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[34952] = { id = 34952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Freund meines Feindes", description = "Hallvalor ist die angestammte Heimat des Klans der Brennenden Klinge. Da sie so dicke Kumpels sind, erlaubt der Kriegshymnenklan den Klingenmeistern und ihren Schamanen, in Nagrand zu bleiben, während sie alle anderen Klans von dort vertreiben.\n\nBla, bla, bla.\n\nIch sage: Die Freunde meines Feindes sind meine Feinde. Mehr muss ich nicht wissen!", sourceObjective = "Tötet 15 Truppen der Brennenden Klinge in Hallvalor.", completion = "Ihr habt uns einen großen Gefallen im Kampf gegen den Klan der Brennenden Klinge erwiesen, Jungchen. Und so etwas vergessen wir nicht.\n\nLasst uns uns in einer Stunde treffen und zur Feier ein Bräu trinken. Die Rechnung geht auf mich.", sourceObjectiveStatus = "unverified-source-field" }
quests[34953] = { id = 34953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blut der Brennenden Klinge", description = "Hallvalor ist die angestammte Heimat meines Klans, der Brennenden Klinge. Als der neue Kriegsherr und seine Familie an die Macht kamen, wurde ich verbannt, weil ich ein Halbblut bin.\n\nIch will Gerechtigkeit.\n\nIch gehe mal davon aus, dass es Euch nichts ausmacht, zu töten. Nicht, dass Ihr die Wahl hättet.", sourceObjective = "Tötet 15 Truppen der Brennenden Klinge in Hallvalor.", completion = "Ihr habt uns einen großen Gefallen im Kampf gegen den Klan der Brennenden Klinge erwiesen, Jungchen. Und so etwas vergessen wir nicht.\n\nLasst uns uns in einer Stunde treffen und zur Feier ein Bräu trinken. Die Rechnung geht auf mich.", sourceObjectiveStatus = "unverified-source-field" }
quests[34954] = { id = 34954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klinge selbst", description = "Als sie mich in Ketten legten, nahm der Ausbilder der Brennenden Klinge, Luhk der Scharfäugige, meine Klinge an sich. Er ist ein ehrenhafter Orc, selbst wenn seine Ausbildungsmethoden kontraproduktiv sein mögen.\n\nIch will meine Klinge zurück, {class}.", sourceObjective = "Sichert Lantresors Klinge von Ausbilder Luhk.", progress = "Ein Klingenmeister ohne seine Klinge ist überhaupt kein Klingenmeister.", completion = "Wenn Ihr Luhk besiegen könnt, gibt es für Euch vielleicht doch noch Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[34955] = { id = 34955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht ohne meine Ehre", description = "Die Klinge ist nicht der einzige wichtige Gegenstand, den ein Klingenmeister mit sich führt.\n\nSobald er seine letzten Prüfungen in der Höhle der Meister abgeschlossen hat, wird einem Klingenmeister die Ehre gewährt, das Banner der Brennenden Klinge zu tragen.\n\nAls mein Anliegen, meinen rechtmäßigen Platz innerhalb des Klans wieder einzunehmen, auf taube und feige Ohren fiel, wurde ich dieser Ehre beraubt.\n\nOhne Zweifel wird mein Banner irgendwo in Hallvalor verwahrt. Sie werden es einem anderen angehenden Klingenmeister übergeben, wenn sie es nicht vorher verbrennen.", sourceObjective = "Sucht nach dem Banner des Klingenmeisters in einer Truhe der Brennenden Klinge.", progress = "Habt Ihr mein Banner?", completion = "Ich erwarte nicht, dass Ihr die Bedeutung dessen erfasst, was Ihr soeben getan habt.\n\nEines Tages werdet Ihr es vielleicht verstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34956] = { id = 34956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft mich in der Höhle", description = "Es ist Zeit, {class}. Zeit, sich den Meistern zu stellen.", sourceObjective = "Trefft Euch mit Lantresor von der Klinge in der Höhle der Meister.", completion = "Ihr habt es geschafft. Sehr gut.\n\nAber hier reinzukommen, war nichts im Vergleich zu dem, was Euch noch erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[34957] = { id = 34957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung der Meister", description = "Die Zeit ist gekommen, die Meister der Brennenden Klinge herauszufordern.\n\nBegebt Euch ans Ende der Höhle. Dort werdet Ihr den Herausforderungsring finden, und mit ihm die Meister, die auf ihn hinabblicken.\n\nZieht das Schwert aus der Mitte des Rings, um Eure Herausforderung auszusprechen. Mein Klan schätzt Ehre über alles und wird Eurer Forderung nach einem Gerichtskampf nachkommen.\n\nAls Preis werdet Ihr mit Eurem Leben von dannen ziehen dürfen... oder Ihr werdet tot sein.", sourceObjective = "Überlebt den Gerichtskampf des Klans der Brennenden Klinge.", completion = "Ein großer Sieg über den Klan der Brennenden Klinge!\n\nDiese neue Kriegsfürstin, Azuka Klingenwut, scheint eine mächtige Gegnerin zu sein. Wir müssen sie und ihre Klingenmeister im Auge behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[34958] = { id = 34958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Schatten des Weltenbrechers", description = "Es sieht so aus, als würden wir bald auf ein weiteres Hindernis treffen: diesen übertrieben großen Panzer, der in Richtung des Dunklen Portals ausgerichtet ist. Ich glaube, sie nennen ihn den \"Eisernen Weltenbrecher\".\n\nWenn ich ein paar Informationen zur Funktionsweise hätte, dann könnte ich vielleicht herausfinden, wie er aufzuhalten ist. Vielleicht tragen diese Maschinisten und Arbeiter ein paar Unterlagen mit sich herum?", sourceObjective = "Besorgt die Weltenbrecherpläne von Schwarzfelsorcs im Schwarzfelssteinbruch.", progress = "Habt Ihr es geschafft?", completion = "Mmm... ja... sieht einfach genug aus.\n\n<Der Zwerg blättert die Seiten um und scheint Eure Gegenwart kaum mehr zu bemerken.>", sourceObjectiveStatus = "unverified-source-field" }
quests[34959] = { id = 34959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreckenskolben", description = "Die Eiserne Horde hat gnadenlos einen friedlichen Draeneiaußenposten überrannt.\n\nInnerhalb weniger Minuten haben sie die Stadt mit einer Maschine, die sie Schreckenskolben nennen, dem Erdboden gleich gemacht.\n\nZerstört sie.", sourceObjective = "Vernichtet Schreckenskolben.", completion = "Diese Maschine wird keine Draeneileben mehr fordern. Habt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[34960] = { id = 34960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gabe des Landes", description = "Die Eisranken im Zitternden Graben haben eine hohe Resistenz gegen niedrige Temperaturen entwickelt. Es könnte sich als nützlich erweisen, sie als Material für den Ausbau der Garnison zu verwenden.", sourceObjective = "Sammelt 30 gefrorenes Pflanzenmaterial.", progress = "Euer Einfallsreichtum ist erstaunlich.", completion = "Das nenn ich ja mal praktisch! Das miese Wetter zerstört in Windeseile unsere Seilvorräte, weshalb wir dringend eine Alternative benötigen. Ihr habt mit Eurem Fund wirklich einen Volltreffer gelandet!", sourceObjectiveStatus = "unverified-source-field" }
quests[34962] = { id = 34962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khadgars Plan", description = "Dank Euch haben wir die Eiserne Horde in die Enge gedrängt.\n\nBald wird es Zeit, die Stadt Shattrath zu erstürmen, um sie zurückzuschlagen.\n\nVorher müssen wir noch Khadgar und einige neue Verbündete treffen.", sourceObjective = "Sprecht mit Khadgar beim Tor von Shattrath.", completion = "Mit Durotan, Draka und Gazlowe habt Ihr ganze Arbeit geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[34963] = { id = 34963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khadgars Plan", description = "Shattrath darf nicht in die Hände der Eisernen Horde fallen. Wieder einmal muss ich mir die Hände blutig machen.\n\nWir werden Khadgar mitteilen, dass wir bereit sind, die Stadt zu betreten und das, was uns gehört, zurückzufordern.", sourceObjective = "Sprecht mit Khadgar beim Tor von Shattrath.", completion = "Bei Maraad, Yrel und Thaelin habt Ihr ganze Arbeit geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[34964] = { id = 34964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Scharfseher erwartet Euch", description = "Man bittet um Eure Anwesenheit am Thron der Elemente, {name}.\n\nScharfseher Drek'Thar hat im Wind den Ruf der Zorne vernommen und sich daraufhin aufgemacht, mit den Elementen Zwiesprache zu halten.\n\nDer Scharfseher hat eine Botschaft geschickt, dass Ihr am Thron der Elemente zu ihm stoßen sollt.\n\nGeht und findet heraus, was die Elemente von Euch wollen.", sourceObjective = "Findet Scharfseher Drek'Thar beim Thron der Elemente.", completion = "Throm-Ka, {name}. In Nagrand geht es nicht mit rechten Dingen zu. Gut, dass Ihr hier seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[34965] = { id = 34965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audienz am Thron", description = "Bereits kurz nach meiner Ankunft in Nagrand trug der Wind die Stimme von Kalandrios an meine Ohren.\n\nEs ist eine große Ehre, zum Thron der Elemente gerufen zu werden, doch mein Herz litt unter der düsteren Vorahnung, worum es gehen würde.\n\nIn der Luft liegt eine Krankheit, die ich überall um uns herum spüre. Sie umfängt alles Leben hier... fesselnd... erstickend...\n\nKommt! Es wird Zeit, mit den Zornen in Kontakt zu treten und ihnen unsere Hilfe anzubieten. Ein unsichtbarer Schatten ist auf das Tal gefallen und womöglich ist es an uns, ihn zu entfernen.", sourceObjective = "Haltet mit den Zornen am Thron der Elemente Zwiesprache.", completion = "Ich fürchte, dass die Störung ernster ist, als ich dachte.\n\nWas auch immer dahinter steckt... es bedroht die elementaren Verbindungen, die die Welt zusammenhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[34967] = { id = 34967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Geplünderte Beute" }
quests[34968] = { id = 34968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Eisbedeckte Vorräte" }
quests[34969] = { id = 34969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Serena beschworen" }
quests[34970] = { id = 34970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenkartenset des Dunkelmond-Jahrmarktes", description = "Jetzt, da Ihr alle Karten des Sets gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Eisenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[34971] = { id = 34971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wahre Art zu reisen", description = "Nennt mich übervorsichtig, aber ich habe mir ein paar Leuchtfeuer aufgehoben. Nur für den Fall, dass wir hier schnell verschwinden müssen.\n\nIch bin froh, dass es nicht nötig war, aber wir könnten die Flugmöglichkeit zum Arsenal immer noch nutzen.\n\nSeid Ihr bereit, Kommandant?", sourceObjective = "Sprecht mit Morketh Klingenschrei in Vol'jins Stolz.", completion = "Der Außenposten ist fertiggestellt und vollkommen einsatzbereit. Außerdem haben wir genug Material, um eine ganze Armee auszustatten – Eure Armee!", sourceObjectiveStatus = "unverified-source-field" }
quests[34972] = { id = 34972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rüstung verstärken", sourceObjective = "Es hat einiges an Schweiß gekostet, aber seht Euch nur dieses hübsche Arsenal an.\n\nIch habe Eure Soldaten hier bereits mit der neuen Ausrüstung ausgestattet, aber ich möchte noch mehr für Euch tun.\n\nEs wäre mir eine große Ehre, wenn Ihr mich in Eurer Hauptgarnison arbeiten lassen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[34973] = { id = 34973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondkartenset des Dunkelmond-Jahrmarktes", description = "Jetzt, da Ihr alle Karten des Sets gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Mondkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[34974] = { id = 34974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionenkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Sets gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Visionenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[34975] = { id = 34975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegskartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Sets gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Kriegskartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[34976] = { id = 34976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bomben werfen", description = "Zur Festung der Gordunni führt nur ein einziger Weg und der ist gegen Großangriffe gut verteidigt.\n\nZum Glück erwarten sie nicht, dass nur wir beide versuchen werden, dort einzubrechen.\n\nDies ist eine gute Gelegenheit, ihre Verteidigungsanlagen außer Gefecht zu setzen und unseren Kanonieren hinten im Artillerieturm einige Zielübungen zu verschaffen.\n\nNehmt diese Rauchgranaten und benutzt sie unterwegs, um einen Artillerieschlag auf ihre Katapulte einzuleiten.", sourceObjective = "Führt Artillerieangriffe auf die Lager der Felswerfer der Gordunni in der Gordalfestung durch.", completion = "Wir sind drin! Es gibt viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[34977] = { id = 34977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorratswiederbeschaffung", description = "Wir scheinen gerade rechtzeitig eingetroffen zu sein!\n\nDie Gordunni haben Ausrüstung für die Eiserne Horde verzaubert und es sieht aus, als wurde ihre letzte Lieferung noch nicht abgeholt.\n\nWir könnten dieses Zeug viel besser in unserem Artillerieturm gebrauchen! Machen wir Jagd auf diese Frachtcontainer. Ich habe ein paar Signalfackeln mitgebracht, mit denen wir sie auf dem Luftweg abtransportieren lassen können, wenn wir die Ladung gesichert haben.", sourceObjective = "Bergt 6 Lieferungen der Eisernen Horde.", completion = "Alles klar, das sollte der letzte von ihnen gewesen sein.\n\nDas ist zwar nicht dasselbe wie die Rückeroberung von Shattrath, doch wenn ich weiß, dass die Eiserne Horde diese Vorräte nicht in die Hände bekommen wird, macht mich das schon ein wenig zufriedener.", sourceObjectiveStatus = "unverified-source-field" }
quests[34978] = { id = 34978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschätztes Plündergut", description = "Die Gordunni haben das Volk von Shattrath seit der Gründung der Stadt immer wieder heimgesucht. Im Lauf der Zeit haben sie eine Unmenge an Waffen angesammelt, die sie während ihrer Überfälle von unseren Verteidigern erbeutet haben.\n\nEs wäre sehr praktisch, wenn wir diese Waffen unseren Soldaten in die Hände drücken könnten, und ich persönlich würde sie den Ogern liebend gerne abnehmen.\n\nSolange wir hier drin sind, tut mir doch den Gefallen und sammelt alle Waffen ein, auf die Ihr stoßt.", sourceObjective = "Sammelt 6 Streitkolben der Wächter von Shattrath. Ihr findet sie bei Knüpplern oder Spaltern der Gordunni in der Gordalfestung.", progress = "Habt Ihr irgendwelche Waffen finden können?", completion = "Vielen Dank, Kommandant. Damit wurde eine große Schmach vom Vermächtnis von Shattrath getilgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[34979] = { id = 34979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchbruch", description = "Um die Festung zu sichern, müssen wir den Hexenfürsten Morkurk töten, aber noch nicht sofort.\n\nSeine drei Stellvertreter Vorgorsh, Zulmork und Cromaug sind allesamt mächtige Magier, die alle Morkurk gegenüber ausgesprochen loyal sind.\n\nWahrscheinlich werden sie dem Hexenfürsten zu Hilfe eilen, wenn wir ihn direkt angreifen. Schalten wir besser erst sie aus, damit das nicht passieren kann.", sourceObjective = "Tötet Wesir Vorgorsh, Wesir Zulmork und Wesir Cromaug.", completion = "Jetzt da wir die Wesire los sind, wird der ganze Verzauberungshandel der Gordunni mit der Eisernen Horde zusammenbrechen!\n\nNun können wir uns Morkurk zuwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[34980] = { id = 34980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fürst der Gordunni", description = "Hexenfürst Morkurk ist der Anführer der Gordunni. Wir müssen ihn töten, um an das Jovit zu kommen, das wir für unseren Artillerieturm brauchen.\n\nMorkurk ist ein fähiger Magier, also seid auf der Hut. Hier, nehmt diesen Raketenrucksack und benutzt ihn, um seiner tödlichen Magie auszuweichen.\n\nArchenon poros!", sourceObjective = "Besiegt Hexenfürst Morkurk in der Gordalfestung.", completion = "Großartige Arbeit, Kommandant! Euren Fähigkeiten im Kampf kann wirklich niemand das Wasser reichen. Es ist mir eine Ehre, Euer Rüstungsschmied sein zu dürfen!\n\nGehen wir zum Außenposten zurück, damit wir uns einen Überblick über unsere neuen Vorräte verschaffen können. Ich habe noch ein paar Leuchtfeuer über, damit wir uns einen Rückflug rufen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[34981] = { id = 34981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wahre Art zu reisen", description = "Nennt mich übervorsichtig, aber ich habe mir ein paar Leuchtfeuer aufgehoben. Nur für den Fall, dass wir hier schnell verschwinden müssen.\n\nIch bin froh, dass es nicht nötig war, aber wir könnten die Flugmöglichkeit zum Artillerieturm immer noch nutzen.\n\nSeid Ihr bereit, Kommandant?", sourceObjective = "Sprecht mit Miall in Fort Wrynn.", completion = "Der Außenposten ist fertiggestellt und vollkommen einsatzbereit. Außerdem haben wir genug Material, um eine ganze Armee auszustatten – Eure Armee!", sourceObjectiveStatus = "unverified-source-field" }
quests[34982] = { id = 34982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rüstung verstärken", sourceObjective = "Es hat einiges an Schweiß gekostet, aber seht Euch nur diesen hübschen Artillerieturm an.\n\nIch habe Eure Soldaten hier bereits mit der neuen Ausrüstung ausgestattet, aber ich möchte noch mehr für Euch tun.\n\nEs wäre mir eine große Ehre, wenn Ihr mich in Eurer Hauptgarnison arbeiten lassen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[34983] = { id = 34983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dropping Bombs Tracking" }
quests[34984] = { id = 34984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supply Recovery Tracking" }
quests[34985] = { id = 34985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prized Repossessions Tracking" }
quests[34986] = { id = 34986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Punching Through Tracking" }
quests[34987] = { id = 34987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pulververschwörung", description = "Hey, es gibt ein Problem.\n\nMein Kumpel Thaelin, das alte Mechanikergenie, hat diesen Zünder aus Einzelteilen der Schwarzfelsorcs zusammengeschraubt, aber um damit überhaupt Schaden anzurichten, brauchen wir noch Schießpulver.", sourceObjective = "Findet ein Fass mit Schwarzfelspulver und bringt es zu Hansel Bleihand.", progress = "Macht ja keinen Blödsinn mit dem Schießpulver!", completion = "Wowhohoho, haaaaa!", sourceObjectiveStatus = "unverified-source-field" }
quests[34991] = { id = 34991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zur... Rettung?", description = "Im Pergament des Staubs steht geschrieben: \"Lasst die Federlosen einander bekämpfen, auf dass unsere Krallen unbefleckt bleiben!\" Dass der Oberste Rabensprecher diesen Tag vorhergesehen hat, zeigt uns wieder, wie weise er ist.\n\nAuf dem Hügel im Westen lebt eine große Bestie, bekannt als Steinschuppe, die einen der Unsrigen entführt hat. Trotz zahlreicher Versuche ist es uns nicht gelungen, die Bestie zu besiegen.\n\nGeht und beweist Euch, indem Ihr die Bestie erschlagt und Tillik rettet! Erfüllt Euer Schicksal im Namen der Rabenmutter!", sourceObjective = "Rettet \"Tillik\" aus den Klauen der Bestie Steinschuppe auf dem Knarzwaldpass.", progress = "Tilliks Verschwinden hat im Schwarm große Trauer verursacht.", completion = "Tillik! Mein werter Freund! Bin ich froh über deine Rückkehr! Die Akolythen haben deine geistreiche Konversation nach den abendlichen Gebeten alle vermisst.\n\n<Iktis sieht wieder zu Euch.>\n\nJa, nun ist Eure Prüfung erledigt. Ihr habt die Anforderungen des Pergaments des Staubs erfüllt!", sourceObjectiveStatus = "unverified-source-field" }
quests[34992] = { id = 34992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sägewerk" }
quests[34993] = { id = 34993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufnahme in die eigenen Reihen", sourceObjective = "Es war nicht einfach, Euren Turm instand zu setzen. Wenn es Euch recht ist, würde ich mich nun gerne Eurer Unternehmung anschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34994] = { id = 34994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für immer jung", description = "Diese ganze Herumsitzerei ist schlecht fürs Geschäft!\n\nIch muss einen Weg finden, wie ich einige der mir entgangenen Profite wieder hereinholen kann.\n\nDie Frauen der Draenei sind vom Aussehen ihrer Hörner besessen.\n\nIch habe gehört, wie eine von ihnen über eine Wurzel sprach, die im Klingenmondflor wächst und die den Hornabrieb oder sowas reduzieren soll.\n\nIch wette, ich könnte einen netten Gewinn machen, wenn ich ihnen solche Wurzeln verkaufen würde.\n\nIch gebe Euch einen Anteil, wenn Ihr mir dabei helft, mir einen Vorrat zu beschaffen.", sourceObjective = "Sammelt Jungwurzeln für Beezil.", progress = "Habt Ihr irgendwelche Jungwurzeln gefunden?", completion = "Hmm... wie soll ich das hier bloß gescheit verpacken?\n\nIch habe eine Idee!\n\n<Beezil schreibt Jungwurzel auf ein Etikett und klebt es auf eine Flasche Schlangenöl.>\n\n<Er wirft die Flasche Jungwurzel hinter sich in die Büsche.>\n\nPerfekt!", sourceObjectiveStatus = "unverified-source-field" }
quests[34995] = { id = 34995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestraft die Botani", description = "Gidwin geht es schon viel besser. Vielen Dank, {name}.\n\nIch kann nicht glauben, dass die Draenei so lange an der Seite dieser schrecklichen Monster gelebt haben.\n\nVielleicht sollten wir diesen Tieren mal zeigen, was passiert, wenn man sich mit einem Azerother anlegt.", sourceObjective = "Tötet 5 Botani.", completion = "Das ist schon eher meine Kragenweite! Hervorragende Arbeit dort draußen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[34996] = { id = 34996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faulende Flussbestien", description = "Diese Botani stecken alle Flusskreaturen der Gegend über eine merkwürdige, fleischfressende Pflanze an.\n\nIch fürchte, diese Infektion könnte sich bis auf unsere Leute ausbreiten.\n\nWenn Ihr verseuchte Flussbestien seht, tötet die blühenden Pflanzen, die in ihren Leichen hausen... bevor sie Euch töten.", sourceObjective = "Tötet 5 blühende Mandragoras.", progress = "Wir müssen diesen Befall beenden.", completion = "Diese Neuigkeiten sind mehr als beunruhigend. Ich bin schockiert, dass der Befall sich so schnell verbreiten konnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[34997] = { id = 34997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlummerblüte", description = "Hm?... Ach du liebe Zeit, ich bin wohl schon wieder eingenickt.\n\nMit diesen Schlummerblüten hat man wirklich nichts als Ärger. Gerade noch kämpfe ich gegen Botani und im nächsten Augenblick träume ich, dass ich als Elekk mit den Flussbestien tanze.\n\n*Gähn* Wir sollten wirklich etwas wegen dieser Schlummerblü... *Gähn*... ZZZZzzzzzzzz\n\n<Ihr sammelt eine Handvoll der kleinen Kiesel ein, die neben dem schlafenden Draenei liegen.>", sourceObjective = "Benutzt die gesammelten Kiesel, um die Schlummerblüten zum Platzen zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34998] = { id = 34998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klauenwacht", description = "Ihr werdet Euch sicher bereits über all die Geschichten um diesen Fluch gewundert haben. Was könnte einen majestätischen Arakkoa zu... nun, zu... so etwas verunstalten?\n\n<Zwischen Reshads gefleckten Federn kommt eine gekrümmte Hand hervor, mit der er sich durch sein Gesicht streift.>\n\nEin Rabe steht bereit, um Euch zur Klauenwacht zu fliegen. Dort werdet Ihr alles über den Ursprung dieses Fluches erfahren.\n\nZeigt der Klauenwache Kurekkdas Auge von Anzu. Von dort aus wird er Euch führen.", sourceObjective = "Bringt das Auge von Anzu zu Klauenwache Kurekk in der Klauenwacht. Sprecht mit Himmelsklaue Meshaal, um einen Flug zu organisieren.", progress = "Reshad hat einen Fremden geschickt? Ihr müsst sehr wichtig sein... oder sehr gefährlich.", completion = "<Kurekk starrt auf die Kugel.>\n\nIst es... das, was ich denke, das es ist?\n\nWir müssen es zum Altar der Klauen bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34999] = { id = 34999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsterblicher Hass", description = "Das Blut des toten Gottes Sethe sammelt sich in diesen Teichen, und damit auch sein Hass auf Rukhmar und Anzu.\n\nSo heftig war dieser Hass, dass er noch jetzt das Blut in Wallung zu versetzen vermag, selbst wenn er bereits vor Äonen von den anderen Göttern ermordet wurde.\n\nIch brauche das geronnene Blut, das diese bösartigen Kreaturen zusammenhält.\n\nEs gibt nichts, was die Jünger mehr fürchten als die Macht dieses Fluches – was also, wenn wir ihn gegen sie einsetzen könnten?", sourceObjective = "Sammelt 15 geronnenes Blut von Sethe in der Sethekkniederung.", progress = "Meinen Versuchen, das gesammelte Blut einzufangen, war kein Erfolg beschieden. Es zersetzt sich und verflüchtigt sich, wenn es von Sethes Knochen getrennt wird.\n\nDoch ich hege große Hoffnungen für diese geronnene Form!", completion = "Ausgezeichnet, wirklich ausgezeichnet. Los, werft sie nur in den Kessel.", sourceObjectiveStatus = "unverified-source-field" }
quests[35000] = { id = 35000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus dem Himmel verbannt", description = "Die Jünger werfen schon seit Generationen ihre Feinde in die Tiefe.\n\nDen Teichen wohnt Sethes letzter Fluch inne, der die Arakkoa mit Visionen der Finsternis und höllischem Schmerz foltert. Der Geist quält sich, der Körper windet sich und die Flügel welken dahin.\n\nDie meisten Arakkoa sterben oder verlieren den Verstand. Nur die Stärksten vermögen ihm zu widerstehen. Sucht sie auf und benutzt das Auge von Anzu, um sie wieder zu sich kommen zu lassen.\n\nDoch habt acht, denn die Jünger von Sethe haben es auch auf diese Überlebenden abgesehen, um Ihre Reihen zu füllen.", sourceObjective = "Wendet das Auge von Anzu auf 8 verfluchte Arakkoa an.", completion = "Sie durchlitten ein Schicksal noch schlimmer als der Tod, doch jetzt sind sie endlich frei.", sourceObjectiveStatus = "unverified-source-field" }
quests[35001] = { id = 35001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blick des Rabengotts", description = "Die Sethekk züchten abscheuliche Windnattern aus Sethes Blut und Gebeinen. Mit diesen Kreaturen werden Sie den Himmel entzwei reißen.\n\nDie Nester sind durch starke Zauber geschützt, aber Anzus Blick sollte sie mit Leichtigkeit durchdringen können.\n\nLasst uns die Nester finden und zerstören!", sourceObjective = "Zerstört mit dem Auge von Anzu 4 Windnatternester.", completion = "<Als die Kugel den Altar berührt, flammt die Kerze in der Nähe auf.>", sourceObjectiveStatus = "unverified-source-field" }
quests[35002] = { id = 35002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sethes Söhne", description = "Viele Jahre sind vergangen, seit jemand Kontakt zu Anzu aufgenommen hat. Er schied dahin, genau wie Terokk, und suchte Zuflucht in den Schatten.\n\nWenn wir ihn zurücklocken wollen, müssen wir ein Opfer darbieten.\n\nSethe hat uns allen den Himmel genommen. Es wäre doch nur angemessen, seinen Kindern dafür die Schwingen zu nehmen.", sourceObjective = "Sammelt 6 Windnatterflügel.", progress = "<Eine große Schale wartet auf eine Opfergabe an den Rabengott.>", completion = "<Ihr legt die Schwingen in die Schale und hört leises Rascheln von Federn irgendwo über Euch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[35003] = { id = 35003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterbrecht das Ritual", description = "Ich konnte diesen Fluch nicht brechen und habe mich vor langer Zeit damit abgefunden, in der Dunkelheit zu ruhen.\n\nDie Sethekk vollziehen dunkle Rituale, um mich zurückzuholen und mich nach und nach Sethes Willen zu unterwerfen. Sollten sie Erfolg haben, wird Sethe mich einen dunklen Mantel über den Horizont legen lassen und die Welt in seinem Blut tränken.\n\nUnterbrecht ihre Rituale und befreit mich. Dann stellen wir gemeinsam sicher, dass Sethe auch weiterhin tot bleibt.", sourceObjective = "Zerstört die Sethekkritualkreise, indem Ihr darüberlauft.", completion = "Ah... Ich fühle, wie ihre Umklammerung sich löst.\n\nDanke, Sterblicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[35004] = { id = 35004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diener eines toten Gottes", description = "Sogar im Tod übt Sethe noch Einfluss aus. Der Kult der Sethekk entstand unter seinem Einfluss: angeführt von einem falschen König, der dem toten Gott dient.\n\nBringt ihre Propheten zum Schweigen, denn sie arbeiten auf eine Zukunft schwarzer Meere und verdorbener Himmel hin.\n\nBesiegt ihre auserwählten Feldherren, denn sie haben sich einer Lüge verschrieben.", sourceObjective = "Tötet 6 Propheten der Sethekk und 6 Auserwählte der Sethekk in der Sethekkniederung.", completion = "Stärke kommt nicht von Waffen und fanatischem Eifer.\n\nSie wandten sich Sethe zu, weil sie zu schwach waren, dem Tod entgegenzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35005] = { id = 35005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereit für die Schlacht", description = "Hier oben gibt es keine Möglichkeit, sich zu verstecken. Wir müssen in Bewegung bleiben, und dafür müssen wir mitten durch das Herz der Eisernen Horde.\n\nHöchste Zeit, dass wir diese unbewaffneten Gefangenen zu einer Armee machen.", sourceObjective = "Erbeutet 30 Schwarzfelswaffen.", progress = "Die Gefangenen sind nicht weniger mutig als Ihr oder ich, {name}. Gebt Ihnen Waffen und einen Funken Hoffnung, und schon kämpfen sie wie die Löwen.", completion = "Gut gemacht, {name}.\n\nDoch steckt Eure Waffe noch nicht fort – jetzt kommt erst die RICHTIGE Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[35006] = { id = 35006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giftstarre", description = "Es werden noch weitere Leute der Karawane vermisst.\n\nIch vermute, dass sie von den Botani in den Klingenmondflor verschleppt wurden.\n\nIhr müsst sie retten, {name}. Ihr seid unsere einzige Hoffnung.\n\nHier, nehmt etwas von dem Elixier, das ich gerade hergestellt habe. Ihr werdet es sehr wahrscheinlich brauchen.", sourceObjective = "Rettet die vermissten Reisenden.", completion = "Das, was Ihr heute für mich getan habt, werde ich niemals begleichen können. {name}.\n\nIch stehe wirklich tief in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[35007] = { id = 35007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Euch mit den Ritualisten", description = "Unser Bruder Sekara ging mit einigen anderen des Schwarms zum Rabenskar, um dort das große Reinigungsritual durchzuführen.\n\nSeit einem Tag ist keiner von ihnen zum Nest zurückgekommen, um Vorräte zu holen. Vermutlich sind sie in ihre Gebete vertieft.\n\nIch würde ja gerne nach ihnen sehen, aber ich muss überprüfen, ob die Schreiberin die Abschrift meiner letzten Predigt nicht verfälscht hat. Könntet Ihr nach ihnen sehen? Ich komme nach, sobald ich... ach, wer weiß...", sourceObjective = "Sprecht mit Rabensprecher Sekara im Rabenskar.", completion = "Endlich hat die Rabenmutter unsere Gebete erhört!", sourceObjectiveStatus = "unverified-source-field" }
quests[35009] = { id = 35009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anrufung der Rabenmutter", description = "Nun ist alles bereit für das Ritual der Anrufung, das die Rabenmutter ins Nest zurückbringen wird.\n\nIhr habt alle Euch auferlegten Prüfungen bestanden, daher ist es angemessen, dass Ihr Euch uns anschließt und mit uns gemeinsam das Ritual durchführt.\n\nSchon bald wird die Rabenmutter vor uns erscheinen! Oh ja, meine Federn zittern vor freudiger Erwartung!\n\nSprecht mich an, sobald Ihr bereit seid!", sourceObjective = "Unterstützt den Obersten Rabensprecher Krikka beim Anrufungsritual.", completion = "Ihr habt meinem kleinen Nest von Vergessenen sehr geholfen. Die armen kleinen Kreaturen sind nicht ganz bei Sinnen, aber sie werden von ihrer eigenen Art gejagt und ihre Not bedrückt mich.\n\nIhre fliegenden Artgenossen, die Ihr Jünger nennt, würden die Vergessenen vernichten und meine Kinder zu Sklaven machen.\n\nDas kann ich nicht zulassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[35010] = { id = 35010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Oberste Rabensprecher", description = "Ja, ich wusste, Ihr würdet würdig sein!\n\nIn der Schrift des Glaubens steht geschrieben, dass in einer Zeit der Krise große Zweifel aufkommen werden, doch alles wird, wie es werden soll, wenn wir nur auf die Rabenmutter vertrauen!\n\nKommt, kommt, wir müssen zum Obersten Rabensprecher!", sourceObjective = "Findet den Obersten Rabensprecher Krikka.", completion = "Das Flüstern der Rabenmutter, möge sie gesegnet sein, kündete in der Schriftrolle der Ordnung an, dass wir nach einer Bitte um ein Zeichen innerhalb von dreißig Minuten eine Antwort erhalten würden.\n\nIhr kommt zur rechten Zeit, denn wir haben mit den Vorbereitungen für ihre Ankunft bereits begonnen und brauchen jetzt Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[35011] = { id = 35011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der falsche Klauenkönig", description = "Ikiss war einst ein angesehener Weiser der Jünger, doch seine Suche nach der Wahrheit über den Fall Terokks führte zu seiner eigenen Verbannung.\n\nNach seinem Fall war Ikiss vollkommen von Terokk besessen und behauptete, er sei die Wiedergeburt dieses Helden vergangener Zeiten. Er führt die Sethekk an und verspricht unermessliche Macht in einem neuen Zeitalter der Dunkelheit.\n\nEines müsst Ihr wissen: Ikiss ist nicht der Klauenkönig. Tötet diesen größenwahnsinnigen Narren und durchsucht ihn nach irgendetwas Nützlichem. Er ist bekannt für seine Sammlung mächtiger Schmuckgegenstände.", sourceObjective = "Nehmt Klauenkönig Ikiss den zerkratzten Armreif ab.", progress = "Habt Ihr den falschen König zum Schweigen gebracht?", completion = "Ein Armreif? Interessant... sieht ziemlich einfach aus...", sourceObjectiveStatus = "unverified-source-field" }
quests[35012] = { id = 35012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sethe der tote Gott", description = "Es ist an der Zeit, Sethe ein Ende zu bereiten. Ich habe ihn schon einmal getötet, und mit Eurer Hilfe wird es mir wieder gelingen.\n\nBereitet Euch auf einen schweren Kampf vor: Die Kultisten werden nicht untätig dabei zusehen, wie wir ihren Gott vernichten.", sourceObjective = "Helft Anzu, Sethe bei der Gebrochenen Spitze zu besiegen.", completion = "Sethe ist zum zweiten Mal gestorben, doch sein Fluch besteht weiterhin fort. Es scheint, als würden wir ewig davon verfolgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[35013] = { id = 35013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lithics Geschenk", description = "<Kurekk kneift die Augen zusammen, während er den Reif betrachtet und ihn langsam in seinen Klauen dreht.>\n\nAuf der Innenseite ist eine Inschrift.\n\n\"An meinen Vater, möge Rukhmar deinen Weg erleuchten. In Liebe, Lithic.\"\n\nDas kann nicht sein... Das ist Terokks Armreif! Er war ein Geschenk seiner Tochter, das er jahrelang trug, bis er...\n\nNun, wir sollten ihn lieber zurückgeben.\n\nTerokk hat ein Denkmal für Lithic nicht weit von der Klauenwacht errichtet. Dort sollte er zur Ruhe gebettet werden.", sourceObjective = "Bringt den zerkratzten Armreif zu Lithics Rast.", progress = "Wer... seid Ihr? Warum habt Ihr mich geweckt?", completion = "Dieser Armreif... Ich habe ihn vor langer Zeit für Vater gemacht.\n\nVor dem Fall...", sourceObjectiveStatus = "unverified-source-field" }
